/* DAWAH X — ahmad, অধ্যায় 34 · খণ্ড 34 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][34]=[[6601,6601,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْعَبْدَ إِذَا كَانَ عَلَى طَرِيقَةٍ حَسَنَةٍ مِنْ الْعِبَادَةِ ثُمَّ مَرِضَ قِيلَ لِلْمَلَكِ الْمُوَكَّلِ بِهِ ‏ ‏اكْتُبْ لَهُ مِثْلَ عَمَلِهِ إِذَا كَانَ طَلِيقًا حَتَّى أُطْلِقَهُ أَوْ ‏ ‏أَكْفِتَهُ ‏ ‏إِلَيَّ ‏","","",""],[6602,6602,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَا يَنْزِعُ الْعِلْمَ مِنْ النَّاسِ بَعْدَ أَنْ يُعْطِيَهُمْ إِيَّاهُ وَلَكِنْ يَذْهَبُ بِالْعُلَمَاءِ كُلَّمَا ذَهَبَ عَالِمٌ ذَهَبَ بِمَا مَعَهُ مِنْ الْعِلْمِ حَتَّى يَبْقَى مَنْ لَا يَعْلَمُ فَيَتَّخِذَ النَّاسُ رُؤَسَاءَ جُهَّالًا فَيُسْتَفْتَوْا فَيُفْتُوا بِغَيْرِ عِلْمٍ فَيَضِلُّوا وَيُضِلُّوا ‏","","",""],[6603,6603,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُقْسِطُونَ فِي الدُّنْيَا عَلَى مَنَابِرَ مِنْ لُؤْلُؤٍ يَوْمَ الْقِيَامَةِ بَيْنَ يَدَيْ الرَّحْمَنِ عَزَّ وَجَلَّ بِمَا أَقْسَطُوا فِي الدُّنْيَا ‏","","",""],[6604,6604,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَعْضِ أَعَلَى ‏ ‏الْوَادِي ‏ ‏نُرِيدُ أَنْ نُصَلِّيَ قَدْ قَامَ وَقُمْنَا إِذْ خَرَجَ عَلَيْنَا حِمَارٌ مِنْ ‏ ‏شِعْبِ ‏ ‏أَبِي دُبٍّ ‏ ‏شِعْبِ ‏ ‏أَبِي مُوسَى ‏ ‏فَأَمْسَكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُكَبِّرْ وَأَجْرَى إِلَيْهِ ‏ ‏يَعْقُوبَ بْنَ زَمْعَةَ ‏ ‏حَتَّى رَدَّهُ ‏","","",""],[6605,6605,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا خَائِنَةٍ وَلَا ‏ ‏ذِي غَمْرٍ ‏ ‏عَلَى أَخِيهِ وَلَا تَجُوزُ شَهَادَةُ الْقَانِعِ لِأَهْلِ الْبَيْتِ وَتَجُوزُ شَهَادَتُهُ لِغَيْرِهِمْ ‏ ‏وَالْقَانِعُ الَّذِي يُنْفِقُ عَلَيْهِ أَهْلُ الْبَيْتِ ‏","","",""],[6606,6606,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَطْعَ فِيمَا دُونَ عَشَرَةِ دَرَاهِمَ ‏","","",""],[6607,6607,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ قَالَ إِنَّ امْرَأَتَيْنِ مِنْ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏أَتَتَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِمَا سِوَارَانِ مِنْ ذَهَبٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحِبَّانِ أَنْ سَوَّرَكُمَا اللَّهُ سِوَارَيْنِ مِنْ نَارٍ قَالَتَا لَا وَاللَّهِ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَأَدِّيَا حَقَّ اللَّهِ عَلَيْكُمَا فِي هَذَا ‏","","",""],[6608,6608,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَاصِمُ أَبَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ هَذَا قَدْ احْتَاجَ إِلَى مَالِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ وَمَالُكَ لِأَبِيكَ ‏","","",""],[6609,6609,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏ثُمَّ هِيَ ‏ ‏خِدَاجٌ ‏ ‏ثُمَّ هِيَ ‏ ‏خِدَاجٌ ‏","","",""],[6610,6610,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ كِتَابًا بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏عَلَى أَنْ يَعْقِلُوا مَعَاقِلَهُمْ وَيَفْدُوا ‏ ‏عَانِيَهُمْ ‏ ‏بِالْمَعْرُوفِ وَالْإِصْلَاحِ بَيْنَ الْمُسْلِمِينَ ‏","","",""],[6611,6611,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نَعُدُّ ‏ ‏الِاجْتِمَاعَ إِلَى أَهْلِ الْمَيِّتِ وَصَنِيعَةَ الطَّعَامِ بَعْدَ دَفْنِهِ مِنْ ‏ ‏النِّيَاحَةِ ‏","","",""],[6612,6612,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الصَّلَاتَيْنِ يَوْمَ غَزَا ‏ ‏بَنِي الْمُصْطَلِقِ ‏","","",""],[6613,6613,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ بْنِ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى خَيْرًا مِنْهَا فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيُكَفِّرْ عَنْ يَمِينِهِ ‏","","",""],[6614,6614,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنِي ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَخْبِرْنِي بِأَشَدِّ شَيْءٍ صَنَعَهُ الْمُشْرِكُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِفِنَاءِ ‏ ‏الْكَعْبَةِ ‏ ‏إِذْ أَقْبَلَ ‏ ‏عُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏فَأَخَذَ بِمَنْكِبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَوَى ثَوْبَهُ فِي عُنُقِهِ فَخَنَقَهُ بِهِ خَنْقًا شَدِيدًا فَأَقْبَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخَذَ بِمَنْكِبِهِ وَدَفَعَهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ { ‏أَتَقْتُلُونَ رَجُلًا أَنْ يَقُولَ ‏ ‏رَبِّيَ اللَّهُ وَقَدْ جَاءَكُمْ بِالْبَيِّنَاتِ مِنْ رَبِّكُمْ ‏}","","",""],[6615,6615,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ يُبَايِعُهُ عَلَى الْهِجْرَةِ وَغَلَّظَ عَلَيْهِ فَقَالَ مَا جِئْتُكَ حَتَّى أَبْكَيْتُهُمَا ‏ ‏يَعْنِي وَالِدَيْهِ ‏ ‏قَالَ ‏ ‏ارْجِعْ فَأَضْحِكْهُمَا كَمَا أَبْكَيْتَهُمَا ‏","","",""],[6616,6616,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَصْلَتَانِ ‏ ‏أَوْ ‏ ‏خَلَّتَانِ ‏ ‏لَا يُحَافِظُ عَلَيْهِمَا رَجُلٌ مُسْلِمٌ إِلَّا دَخَلَ الْجَنَّةَ هُمَا يَسِيرٌ وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ تُسَبِّحُ اللَّهَ عَشْرًا وَتَحْمَدُ اللَّهَ عَشْرًا وَتُكَبِّرُ اللَّهَ عَشْرًا فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ فَذَلِكَ مِائَةٌ وَخَمْسُونَ بِاللِّسَانِ وَأَلْفٌ وَخَمْسُ مِائَةٍ فِي الْمِيزَانِ وَتُسَبِّحُ ثَلَاثًا وَثَلَاثِينَ وَتَحْمَدُ ثَلَاثًا وَثَلَاثِينَ وَتُكَبِّرُ أَرْبَعًا وَثَلَاثِينَ ‏ ‏عَطَاءٌ ‏ ‏لَا يَدْرِي أَيَّتُهُنَّ أَرْبَعٌ وَثَلَاثُونَ ‏ ‏إِذَا أَخَذَ مَضْجَعَهُ فَذَلِكَ مِائَةٌ بِاللِّسَانِ وَأَلْفٌ فِي الْمِيزَانِ فَأَيُّكُمْ يَعْمَلُ فِي الْيَوْمِ أَلْفَيْنِ وَخَمْسَ مِائَةِ سَيِّئَةٍ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ هُمَا يَسِيرٌ وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ قَالَ يَأْتِي أَحَدَكُمْ الشَّيْطَانُ إِذَا فَرَغَ مِنْ صَلَاتِهِ فَيُذَكِّرُهُ حَاجَةَ كَذَا وَكَذَا فَيَقُومُ وَلَا يَقُولُهَا فَإِذَا اضْطَجَعَ ‏ ‏يَأْتِيهِ الشَّيْطَانُ فَيُنَوِّمُهُ قَبْلَ أَنْ يَقُولَهَا فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْقِدُهُنَّ فِي يَدِهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ اللَّهِ الْقَوَارِيرِيَّ ‏ ‏سَمِعْتُ ‏ ‏حَمَّادَ بْنَ زَيْدٍ ‏ ‏يَقُولُ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏الْبَصْرَةَ ‏ ‏فَقَالَ لَنَا ‏ ‏أَيُّوبُ ‏ ‏ائْتُوهُ فَاسْأَلُوهُ عَنْ حَدِيثِ التَّسْبِيحِ ‏ ‏يَعْنِي هَذَا الْحَدِيثَ ‏","","",""],[6617,6617,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ رَأَى قَوْمًا تَوَضَّئُوا لَمْ يُتِمُّوا الْوُضُوءَ فَقَالَ ‏ ‏وَيْلٌ لِلْأَعْقَابِ مِنْ النَّارِ ‏","","",""],[6618,6618,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمُهَاجِرَ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ وَالْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏","","",""],[6619,6619,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي مَخْزُومٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أَرَادَ أَنْ يَأْخُذَ أَرْضًا ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏يُقَالُ لَهَا الْوَهْطُ فَأَمَرَ ‏ ‏مَوَالِيَهُ ‏ ‏فَلَبِسُوا آلَتَهُمْ وَأَرَادُوا الْقِتَالَ قَالَ فَأَتَيْتُهُ فَقُلْتُ مَاذَا فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يُظْلَمُ بِمَظْلَمَةٍ فَيُقَاتِلَ فَيُقْتَلَ إِلَّا قُتِلَ شَهِيدًا ‏","","",""],[6620,6620,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ طَلْحَةَ ‏ ‏أَوْ ‏ ‏طَلْحَةَ بْنِ هِلَالٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏صُمْ الدَّهْرَ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ قَالَ وَقَرَأَ هَذِهِ الْآيَةَ ‏ { ‏مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا ‏} ‏قَالَ قُلْتُ إِنِّي أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ قَالَ ‏ ‏صُمْ صِيَامَ ‏ ‏دَاوُدَ ‏ ‏كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا ‏","","",""],[6621,6621,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ فَيَّاضٍ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُمْ يَوْمًا وَلَكَ أَجْرُ مَا بَقِيَ حَتَّى عَدَّ أَرْبَعَةَ أَيَّامٍ ‏ ‏أَوْ خَمْسَةً ‏ ‏شُعْبَةُ ‏ ‏يَشُكُّ ‏ ‏قَالَ ‏ ‏صُمْ أَفْضَلَ الصَّوْمِ صَوْمَ ‏ ‏دَاوُدَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا ‏","","",""],[6622,6622,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَبِي حَصِينٍ ‏ ‏نَعُودُهُ وَمَعَنَا ‏ ‏عَاصِمٌ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو حَصِينٍ ‏ ‏لِعَاصِمٍ ‏ ‏تَذْكُرُ حَدِيثًا ‏ ‏حَدَّثَنَاهُ ‏ ‏الْقَاسِمُ بْنُ مُخَيْمِرَةَ ‏ ‏قَالَ ‏ ‏قَالَ نَعَمْ إِنَّهُ حَدَّثَنَا يَوْمًا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَكَى الْعَبْدُ الْمُسْلِمُ قِيلَ لِلْكَاتِبِ الَّذِي يَكْتُبُ عَمَلَهُ ‏ ‏اكْتُبْ لَهُ مِثْلَ عَمَلِهِ إِذْ كَانَ طَلِيقًا حَتَّى أَقْبِضَهُ أَوْ أُطْلِقَهُ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا بِهِ ‏ ‏عَاصِمٌ ‏ ‏وَأَبُو حَصِينٍ ‏ ‏جَمِيعًا ‏","","",""],[6623,6623,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ يَقُولُ ‏ ‏كُلُّ ‏ ‏حِلْفٍ ‏ ‏كَانَ فِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الْإِسْلَامُ إِلَّا شِدَّةً وَلَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[6624,6624,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ سَلَفٍ وَبَيْعٍ وَعَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ وَعَنْ بَيْعِ مَا لَيْسَ عِنْدَكَ وَعَنْ رِبْحِ مَا لَمْ يُضْمَنْ ‏","","",""],[6625,6625,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَوَاءٍ أَبُو الْخَطَّابِ السَّدُوسِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الْمُثَنَّى بْنَ الصَّبَّاحِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ زَادَكُمْ صَلَاةً فَحَافِظُوا عَلَيْهَا وَهِيَ ‏ ‏الْوَتْرُ ‏ ‏فَكَانَ ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏رَأَى أَنْ يُعَادَ ‏ ‏الْوَتْرُ ‏ ‏وَلَوْ بَعْدَ شَهْرٍ ‏","","",""],[6626,6626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ بْنُ مَيْمُونٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا مِنَّا يُقَالُ لَهُ ‏ ‏أَيُّوبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏مَنْ تَابَ قَبْلَ مَوْتِهِ عَامًا تِيبَ عَلَيْهِ وَمَنْ تَابَ قَبْلَ مَوْتِهِ بِشَهْرٍ تِيبَ عَلَيْهِ حَتَّى قَالَ يَوْمًا حَتَّى قَالَ سَاعَةً حَتَّى قَالَ ‏ ‏فُوَاقًا ‏ ‏قَالَ قَالَ الرَّجُلُ أَرَأَيْتَ إِنْ كَانَ مُشْرِكًا أَسْلَمَ قَالَ إِنَّمَا أُحَدِّثُكُمْ كَمَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏","","",""],[6627,6627,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحَبُّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏كَانَ يَصُومُ نِصْفَ الدَّهْرِ وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ صَلَاةُ ‏ ‏دَاوُدَ ‏ ‏كَانَ يَرْقُدُ شَطْرَ اللَّيْلِ ثُمَّ يَقُومُ ثُمَّ يَرْقُدُ آخِرَهُ ثُمَّ يَقُومُ ثُلُثَ اللَّيْلِ بَعْدَ شَطْرِهِ ‏","","",""],[6628,6628,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ لَمَّا كَانَ بَيْنَ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وعَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏مَا كَانَ وَتَيَسَّرُوا لِلْقِتَالِ فَرَكِبَ ‏ ‏خَالِدُ بْنُ الْعَاصِي ‏ ‏إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَوَعَظَهُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏مَنْ قُتِلَ عَلَى مَالِهِ فَهُوَ شَهِيدٌ ‏","","",""],[6629,6629,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ كُوتِبَ عَلَى مِائَةِ ‏ ‏أُوقِيَّةٍ ‏ ‏فَأَدَّاهَا إِلَّا عَشْرَ ‏ ‏أَوَاقٍ ‏ ‏ثُمَّ عَجَزَ فَهُوَ رَقِيقٌ ‏","","",""],[6630,6630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَتْفِ الشَّيْبِ ‏","","",""],[6631,6631,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَدْرُونَ مَنْ الْمُسْلِمُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ قَالَ تَدْرُونَ مَنْ الْمُؤْمِنُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَنْ أَمِنَهُ الْمُؤْمِنُونَ عَلَى أَنْفُسِهِمْ وَأَمْوَالِهِمْ وَالْمُهَاجِرُ مَنْ هَجَرَ السُّوءَ فَاجْتَنَبَهُ ‏","","",""],[6632,6632,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏إِنِّي لَأُسَايِرُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَمُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏لِعَمْرٍو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَقْتُلُهُ الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏يَعْنِي ‏ ‏عَمَّارًا ‏ ‏فَقَالَ ‏ ‏عَمْرٌو ‏ ‏لِمُعَاوِيَةَ ‏ ‏اسْمَعْ مَا يَقُولُ هَذَا فَحَدَّثَهُ فَقَالَ أَنَحْنُ قَتَلْنَاهُ إِنَّمَا قَتَلَهُ مَنْ جَاءَ بِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي الضَّرِيرَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي زِيَادٍ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[6633,6633,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ فِي السَّفَرِ وَيُفْطِرُ وَرَأَيْتُهُ يَشْرَبُ قَائِمًا وَقَاعِدًا وَرَأَيْتُهُ ‏ ‏يُصَلِّي حَافِيًا وَمُنْتَعِلًا وَرَأَيْتُهُ يَنْصَرِفُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ ‏","","",""],[6634,6634,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنِي ‏ ‏أَسْوَدُ بْنُ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ خُوَيْلِدٍ الْعَنْبَرِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏إِذْ جَاءَهُ رَجُلَانِ يَخْتَصِمَانِ فِي رَأْسِ ‏ ‏عَمَّارٍ ‏ ‏يَقُولُ كُلُّ وَاحِدٍ مِنْهُمَا أَنَا قَتَلْتُهُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لِيَطِبْ بِهِ أَحَدُكُمَا نَفْسًا لِصَاحِبِهِ فَإِنِّي سَمِعْتُ ‏ ‏يَعْنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏كَذَا قَالَ أَبِي ‏ ‏يَعْنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَقْتُلُهُ الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَلَا تُغْنِي عَنَّا مَجْنُونَكَ يَا ‏ ‏عَمْرُو ‏ ‏فَمَا بَالُكَ مَعَنَا ‏ ‏قَالَ إِنَّ أَبِي شَكَانِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطِعْ أَبَاكَ مَا دَامَ حَيًّا وَلَا تَعْصِهِ فَأَنَا مَعَكُمْ وَلَسْتُ أُقَاتِلُ ‏","","",""],[6635,6635,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَمُحَمَّدُ بْنُ يَزِيِدَ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَكْتُبُ مَا أَسْمَعُ مِنْكَ قَالَ نَعَمْ قُلْتُ فِي الرِّضَا وَالسُّخْطِ قَالَ ‏ ‏نَعَمْ فَإِنَّهُ لَا يَنْبَغِي لِي أَنْ أَقُولَ فِي ذَلِكَ إِلَّا حَقًّا ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏فِي حَدِيثِهِ يَا رَسُولَ اللَّهِ إِنِّي أَسْمَعُ مِنْكَ أَشْيَاءَ فَأَكْتُبُهَا قَالَ نَعَمْ ‏","","",""],[6636,6636,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏خَالِدَ بْنَ مَعْدَانَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏جُبَيْرَ بْنَ نُفَيْرٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏أَخْبَرَهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏ابْنُ الْعَاصِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى عَلَيْهِ ثَوْبَيْنِ ‏ ‏مُعَصْفَرَيْنِ ‏ ‏فَقَالَ ‏ ‏إِنَّ هَذِهِ ثِيَابُ الْكُفَّارِ فَلَا تَلْبَسْهَا ‏","","",""],[6637,6637,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا طَلَاقَ فِيمَا لَا تَمْلِكُونَ وَلَا عَتَاقَ فِيمَا لَا تَمْلِكُونَ وَلَا ‏ ‏نَذْرَ ‏ ‏فِيمَا لَا تَمْلِكُونَ وَلَا ‏ ‏نَذْرَ ‏ ‏فِي مَعْصِيَةِ اللَّهِ ‏","","",""],[6638,6638,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏لَمَّا فُتِحَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةُ ‏ ‏قَالَ كُفُّوا السِّلَاحَ إِلَّا ‏ ‏خُزَاعَةَ ‏ ‏عَنْ ‏ ‏بَنِي بَكْرٍ ‏ ‏فَأَذِنَ لَهُمْ حَتَّى صَلَّوْا الْعَصْرَ ثُمَّ قَالَ كُفُّوا السِّلَاحَ فَلَقِيَ مِنْ الْغَدِ رَجُلٌ مِنْ ‏ ‏خُزَاعَةَ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي بَكْرٍ ‏ ‏بِالْمُزْدَلِفَةِ ‏ ‏فَقَتَلَهُ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ خَطِيبًا فَقَالَ ‏ ‏إِنَّ أَعْدَى النَّاسِ عَلَى اللَّهِ مَنْ عَدَا فِي ‏ ‏الْحَرَمِ ‏ ‏وَمَنْ قَتَلَ غَيْرَ قَاتِلِهِ وَمَنْ قَتَلَ ‏ ‏بِذُحُولِ ‏ ‏الْجَاهِلِيَّةِ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّ ابْنِي فُلَانًا ‏ ‏عَاهَرْتُ ‏ ‏بِأُمِّهِ فِي الْجَاهِلِيَّةِ فَقَالَ لَا دَعْوَةَ فِي الْإِسْلَامِ ذَهَبَ أَمْرُ الْجَاهِلِيَّةِ الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْأَثْلَبُ قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْأَثْلَبُ قَالَ ‏ ‏الْحَجَرُ ‏ ‏وَفِي الْأَصَابِعِ عَشْرٌ عَشْرٌ وَفِي ‏ ‏الْمَوَاضِحِ ‏ ‏خَمْسٌ خَمْسٌ وَلَا صَلَاةَ بَعْدَ الصُّبْحِ حَتَّى تَشْرُقَ الشَّمْسُ وَلَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَلَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا وَلَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا وَأَوْفُوا ‏ ‏بِحِلْفِ ‏ ‏الْجَاهِلِيَّةِ فَإِنَّ الْإِسْلَامَ لَمْ يَزِدْهُ إِلَّا شِدَّةً وَلَا تُحْدِثُوا ‏ ‏حِلْفًا ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[6639,6639,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنِي ‏ ‏مَوْلًى لِعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّمْسَ حِينَ غَرَبَتْ فَقَالَ ‏ ‏فِي نَارِ اللَّهِ الْحَامِيَةِ لَوْلَا مَا يَزَعُهَا مِنْ أَمْرِ اللَّهِ لَأَهْلَكَتْ مَا عَلَى الْأَرْضِ ‏","","",""],[6640,6640,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ يَعْرِفْ حَقَّ كَبِيرِنَا وَيَرْحَمْ صَغِيرَنَا ‏","","",""],[6641,6641,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏وَهُوَ يَسْأَلُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏ابْنِ إِدْرِيسَ ‏ ‏قَالَ وَسَأَلَهُ عَنْ الثِّمَارِ وَمَا كَانَ فِي ‏ ‏أَكْمَامِهِ ‏ ‏فَقَالَ ‏ ‏مَنْ أَكَلَ بِفَمِهِ وَلَمْ يَتَّخِذْ ‏ ‏خُبْنَةً ‏ ‏فَلَيْسَ عَلَيْهِ شَيْءٌ وَمَنْ وُجِدَ قَدْ احْتَمَلَ فَفِيهِ ثَمَنُهُ مَرَّتَيْنِ وَضَرْبُ ‏ ‏نَكَالٍ ‏ ‏فَمَا أَخَذَ مِنْ جِرَانِهِ فَفِيهِ الْقَطْعُ إِذَا بَلَغَ مَا يُؤْخَذُ مِنْ ذَلِكَ ثَمَنَ ‏ ‏الْمِجَنِّ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ مَا نَجِدُ فِي السَّبِيلِ ‏ ‏الْعَامِرِ ‏ ‏مِنْ ‏ ‏اللُّقَطَةِ ‏ ‏قَالَ عَرِّفْهَا ‏ ‏حَوْلًا ‏ ‏فَإِنْ جَاءَ صَاحِبُهَا وَإِلَّا فَهِيَ لَكَ قَالَ يَا رَسُولَ اللَّهِ مَا نَجِدُ فِي الْخَرِبِ ‏ ‏الْعَادِيِّ قَالَ فِيهِ وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[6642,6642,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَتْفِ الشَّيْبِ وَقَالَ هُوَ نُورُ الْمُؤْمِنِ وَقَالَ مَا شَابَ رَجُلٌ فِي الْإِسْلَامِ شَيْبَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَمُحِيَتْ عَنْهُ بِهَا سَيِّئَةٌ وَكُتِبَتْ لَهُ بِهَا حَسَنَةٌ ‏","","",""],[6643,6643,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ يُوَقِّرْ كَبِيرَنَا وَيَرْحَمْ صَغِيرَنَا ‏","","",""],[6644,6644,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَدَّ ابْنَتَهُ إِلَى ‏ ‏أَبِي الْعَاصِ ‏ ‏بِمَهْرٍ جَدِيدٍ وَنِكَاحٍ جَدِيدٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فِي حَدِيثِ ‏ ‏حَجَّاحٍ ‏ ‏رَدَّ ‏ ‏زَيْنَبَ ‏ ‏ابْنَتَهُ ‏ ‏قَالَ ‏ ‏هَذَا ‏ ‏حَدِيثٌ ضَعِيفٌ ‏ ‏أَوْ قَالَ ‏ ‏وَاهٍ ‏ ‏وَلَمْ يَسْمَعْهُ ‏ ‏الْحَجَّاجُ ‏ ‏مِنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏إِنَّمَا سَمِعَهُ مِنْ ‏ ‏مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ الْعَرْزَمِيِّ ‏ ‏وَالْعَرْزَمِيُّ ‏ ‏لَا ‏ ‏يُسَاوِي حَدِيثُهُ شَيْئًا وَالْحَدِيثُ الصَّحِيحُ الَّذِي رُوِيَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَرَّهُمَا عَلَى النِّكَاحِ الْأَوَّلِ ‏","","",""],[6645,6645,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَتَانِ مِنْ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِمَا أَسْوِرَةٌ مِنْ ذَهَبٍ فَقَالَ ‏ ‏أَتُحِبَّانِ أَنْ يُسَوِّرَكُمَا اللَّهُ بِأَسْوِرَةٍ مِنْ نَارٍ قَالَتَا لَا قَالَ فَأَدِّيَا حَقَّ هَذَا ‏","","",""],[6646,6646,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏وَمُعَمَّرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَجُوزُ شَهَادَةُ خَائِنٍ وَلَا ‏ ‏مَحْدُودٍ ‏ ‏فِي الْإِسْلَامِ وَلَا ‏ ‏ذِي غِمْرٍ ‏ ‏عَلَى أَخِيهِ ‏","","",""],[6647,6647,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ زَادَكُمْ صَلَاةً وَهِيَ ‏ ‏الْوَتْرُ ‏","","",""],[6648,6648,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي ذَوِي أَرْحَامٍ أَصِلُ وَيَقْطَعُونَ ‏ ‏وَأَعْفُو وَيَظْلِمُونَ وَأُحْسِنُ وَيُسِيئُونَ أَفَأُكَافِئُهُمْ قَالَ لَا إِذًا تُتْرَكُونَ جَمِيعًا وَلَكِنْ ‏ ‏خُذْ بِالْفَضْلِ وَصِلْهُمْ فَإِنَّهُ لَنْ يَزَالَ مَعَكَ مِنْ اللَّهِ ظَهِيرٌ مَا كُنْتَ عَلَى ذَلِكَ ‏","","",""],[6649,6649,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاجِعُ فِي هِبَتِهِ كَالْكَلْبِ يَرْجِعُ فِي قَيْئِهِ ‏","","",""],[6650,6650,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَعَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ جَاءَ ‏ ‏رَجُلٌ ‏ ‏يَنْتِفُ شَعَرَهُ وَيَدْعُو وَيْلَهُ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ قَالَ وَقَعَ عَلَى امْرَأَتِهِ فِي رَمَضَانَ قَالَ ‏ ‏أَعْتِقْ رَقَبَةً قَالَ لَا أَجِدُهَا قَالَ صُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ قَالَ لَا أَسْتَطِيعُ قَالَ أَطْعِمْ سِتِّينَ مِسْكِينًا قَالَ لَا أَجِدُ قَالَ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَقٍ ‏ ‏فِيهِ خَمْسَةَ عَشَرَ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ قَالَ خُذْ هَذَا فَأَطْعِمْهُ عَنْكَ سِتِّينَ مِسْكِينًا قَالَ يَا رَسُولَ اللَّهِ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏أَهْلُ بَيْتٍ أَفْقَرُ مِنَّا قَالَ كُلْهُ أَنْتَ وَعِيَالُكَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَعَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏بِمِثْلِهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَزَادَ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏فِي حَدِيثِهِ وَأَمَرَهُ أَنْ يَصُومَ يَوْمًا مَكَانَهُ ‏","","",""],[6651,6651,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏أَنَّ ‏ ‏نَوْفًا ‏ ‏وَعَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏اجْتَمَعَا فَقَالَ ‏ ‏نَوْفٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَأَنَا ‏ ‏أُحَدِّثُكَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّيْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَعَقَّبَ ‏ ‏مَنْ ‏ ‏عَقَّبَ ‏ ‏وَرَجَعَ مَنْ رَجَعَ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يَثُورَ النَّاسُ بِصَلَاةِ الْعِشَاءِ فَجَاءَ وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ رَافِعًا إِصْبَعَهُ هَكَذَا وَعَقَدَ تِسْعًا وَعِشْرِينَ وَأَشَارَ بِإِصْبَعِهِ السَّبَّابَةِ إِلَى السَّمَاءِ وَهُوَ يَقُولُ أَبْشِرُوا مَعْشَرَ الْمُسْلِمِينَ هَذَا رَبُّكُمْ عَزَّ وَجَلَّ قَدْ فَتَحَ بَابًا مِنْ أَبْوَابِ السَّمَاءِ ‏ ‏يُبَاهِي بِكُمْ الْمَلَائِكَةَ يَقُولُ ‏ ‏يَا مَلَائِكَتِي انْظُرُوا إِلَى عِبَادِي هَؤُلَاءِ أَدَّوْا فَرِيضَةً وَهُمْ يَنْتَظِرُونَ أُخْرَى ‏","","",""],[6652,6652,"","","‏ ‏مَضْرُوبٌ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏وَهَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَسْتَاذَ ‏ ‏قَالَ ‏ ‏هَوْذَةُ الهِزَّانِيُّ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الذَّهَبَ مِنْ أُمَّتِي فَمَاتَ وَهُوَ يَلْبَسُهُ لَمْ يَلْبَسْ مِنْ ذَهَبِ الْجَنَّةِ ‏ ‏وَقَالَ ‏ ‏هَوْذَةُ ‏ ‏حَرَّمَ اللَّهُ عَلَيْهِ ‏ ‏ذَهَبَ الْجَنَّةِ ‏ ‏وَمَنْ لَبِسَ الْحَرِيرَ مِنْ أُمَّتِي فَمَاتَ وَهُوَ يَلْبَسُهُ حَرَّمَ اللَّهُ عَلَيْهِ حَرِيرَ الْجَنَّةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏ضَرَبَ أَبِي عَلَى هَذَا الْحَدِيثِ فَظَنَنْتُ أَنَّهُ ضَرَبَ عَلَيْهِ لِأَنَّهُ خَطَأٌ وَإِنَّمَا هُوَ ‏ ‏مَيْمُونُ بْنُ أَسْتَاذَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَلَيْسَ فِيهِ عَنْ ‏ ‏الصَّدَفِيِّ ‏ ‏وَيُقَالُ إِنَّ ‏ ‏مَيْمُونَ ‏ ‏هَذَا هُوَ ‏ ‏الصَّدَفِيُّ ‏ ‏لِأَنَّ سَمَاعَ ‏ ‏يَزِيدَ بْنِ هَارُونَ ‏ ‏مِنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏آخِرَ عُمُرِهِ وَاللَّهُ أَعْلَمُ ‏","","",""],[6653,6653,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَسْتَاذَ ‏ ‏عَنِ ‏ ‏الصَّدَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ يَشْرَبُ الْخَمْرَ حَرَّمَ اللَّهُ عَلَيْهِ شُرْبَهَا فِي الْجَنَّةِ وَمَنْ مَاتَ مِنْ أُمَّتِي وَهُوَ ‏ ‏يَتَحَلَّى الذَّهَبَ حَرَّمَ اللَّهُ عَلَيْهِ لِبَاسَهُ فِي الْجَنَّةِ ‏","","",""],[6654,6654,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ ‏ ‏كُوتِبَ ‏ ‏عَلَى مِائَةِ ‏ ‏أُوقِيَّةٍ ‏ ‏فَأَدَّاهَا إِلَّا عَشْرَ ‏ ‏أَوَاقٍ ‏ ‏فَهُوَ رَقِيقٌ ‏","","",""],[6655,6655,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي ثُمَامَةَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُوضَعُ الرَّحِمُ يَوْمَ الْقِيَامَةِ لَهَا ‏ ‏حُجْنَةٌ ‏ ‏كَحُجْنَةِ ‏ ‏الْمِغْزَلِ تَتَكَلَّمُ بِأَلْسِنَةٍ ‏ ‏طُلْقٍ ‏ ‏ذُلْقٍ ‏ ‏فَتَصِلُ مَنْ وَصَلَهَا وَتَقْطَعُ مَنْ قَطَعَهَا ‏","","",""],[6656,6656,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏شُعَيْبِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ صُمْ يَوْمًا وَلَكَ عَشَرَةُ أَيَّامٍ قَالَ زِدْنِي يَا رَسُولَ اللَّهِ إِنَّ بِي قُوَّةً قَالَ صُمْ يَوْمَيْنِ وَلَكَ تِسْعَةُ أَيَّامٍ قَالَ زِدْنِي فَإِنِّي أَجِدُ قُوَّةً قَالَ ‏ ‏صُمْ ثَلَاثَةَ أَيَّامٍ وَلَكَ ثَمَانِيَةُ أَيَّامٍ ‏","","",""],[6657,6657,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَلَى ‏ ‏نَوْفٍ الْبِكَالِيِّ ‏ ‏وَهُوَ يُحَدِّثُ فَقَالَ حَدِّثْ فَإِنَّا قَدْ نُهِينَا عَنْ الْحَدِيثِ قَالَ مَا كُنْتُ لِأُحَدِّثُ وَعِنْدِي رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتَكُونُ هِجْرَةٌ بَعْدَ هِجْرَةٍ فَخِيَارُ الْأَرْضِ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏لَخِيَارُ الْأَرْضِ ‏ ‏إِلَى مُهَاجَرِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَيَبْقَى فِي الْأَرْضِ شِرَارُ أَهْلِهَا تَلْفِظُهُمْ الْأَرْضُ وَتَقْذَرُهُمْ نَفْسُ اللَّهِ عَزَّ وَجَلَّ وَتَحْشُرُهُمْ النَّارُ مَعَ الْقِرَدَةِ وَالْخَنَازِيرِ ‏","","",""],[6658,6658,"","","‏ ‏ثُمَّ قَالَ حَدِّثْ فَإِنَّا قَدْ نُهِينَا عَنْ الْحَدِيثِ فَقَالَ مَا كُنْتُ لِأُحَدِّثُ وَعِنْدِي رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ قَوْمٌ مِنْ قِبَلِ الْمَشْرِقِ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ كُلَّمَا قُطِعَ قَرْنٌ نَشَأَ قَرْنٌ حَتَّى يَخْرُجَ فِي بَقِيَّتِهِمْ ‏ ‏الدَّجَّالُ ‏","","",""],[6659,6659,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏فَقُلْتُ حَدِّثْنِي مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَلَا تُحَدِّثْنِي عَنْ التَّوْرَاةِ وَالْإِنْجِيلِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6660,6660,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ الشَّامِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا الْأَشْعَثِ الصَّنْعَانِيَّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ وَغَدَا وَابْتَكَرَ وَدَنَا فَاقْتَرَبَ وَاسْتَمَعَ وَأَنْصَتَ كَانَ لَهُ بِكُلِّ خُطْوَةٍ ‏ ‏يَخْطُوهَا أَجْرُ قِيَامِ سَنَةٍ وَصِيَامِهَا ‏","","",""],[6661,6661,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْرَائِيلَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏هِلَالٍ الْهَجَرِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا خَطَأٌ إِنَّمَا هُوَ ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏سَيْفٍ ‏ ‏عَنْ ‏ ‏رُشَيْدٍ الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏","","",""],[6662,6662,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْقَتِيلُ دُونَ مَالِهِ شَهِيدٌ ‏","","",""],[6663,6663,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَتَاهُ رَجُلٌ يَوْمَ النَّحْرِ وَهُوَ وَاقِفٌ عِنْدَ ‏ ‏الْجَمْرَةِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي حَلَقْتُ قَبْلَ أَنْ أَرْمِيَ فَقَالَ ارْمِ وَلَا حَرَجَ وَأَتَاهُ آخَرُ فَقَالَ إِنِّي ذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ وَأَتَاهُ آخَرُ فَقَالَ إِنِّي أَفَضْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ قَالَ ‏ ‏فَمَا رَأَيْتُهُ سُئِلَ يَوْمَئِذٍ عَنْ شَيْءٍ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏","","",""],[6664,6664,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حُصَيْنٌ ‏ ‏سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ عَمَلٍ ‏ ‏شِرَّةٌ ‏ ‏وَلِكُلِّ ‏ ‏شِرَّةٍ ‏ ‏فَتْرَةٌ ‏ ‏فَمَنْ كَانَتْ ‏ ‏فَتْرَتُهُ ‏ ‏إِلَى سُنَّتِي فَقَدْ أَفْلَحَ وَمَنْ كَانَتْ إِلَى غَيْرِ ذَلِكَ فَقَدْ هَلَكَ ‏","","",""],[6665,6665,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَالْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ كُفِّرَتْ ذُنُوبُهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[6666,6666,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏صُهَيْبًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَتَلَ عُصْفُورًا فِي غَيْرِ شَيْءٍ إِلَّا بِحَقِّهِ سَأَلَهُ اللَّهُ عَزَّ وَجَلَّ عَنْهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[6667,6667,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حُمَيْدٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ بِيَدِهِ الْخَيْرُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏","","",""],[6668,6668,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَنْتِفُوا الشَّيْبَ فَإِنَّهُ نُورُ الْمُسْلِمِ مَنْ شَابَ شَيْبَةً فِي الْإِسْلَامِ كَتَبَ اللَّهُ لَهُ بِهَا حَسَنَةً وَكَفَّرَ عَنْهُ بِهَا خَطِيئَةً وَرَفَعَهُ بِهَا دَرَجَةً ‏","","",""],[6669,6669,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ رَجُلٌ الْجَنَّةَ بِسَمَاحَتِهِ قَاضِيًا وَمُتَقَاضِيًا ‏","","",""],[6670,6670,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَأْخُذَ اللَّهُ ‏ ‏شَرِيطَتَهُ ‏ ‏مِنْ أَهْلِ الْأَرْضِ فَيَبْقَى فِيهَا ‏ ‏عَجَاجَةٌ ‏ ‏لَا يَعْرِفُونَ مَعْرُوفًا وَلَا يُنْكِرُونَ مُنْكَرًا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏وَقَالَ ‏ ‏حَتَّى يَأْخُذَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏شَرِيطَتَهُ ‏ ‏مِنْ النَّاسِ ‏","","",""],[6671,6671,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَقْتُ الظُّهْرِ إِذَا زَالَتْ الشَّمْسُ وَكَانَ ظِلُّ الرَّجُلِ كَطُولِهِ مَا لَمْ يَحْضُرْ الْعَصْرُ وَوَقْتُ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ وَوَقْتُ صَلَاةِ الْمَغْرِبِ مَا لَمْ يَغْرُبْ ‏ ‏الشَّفَقُ ‏ ‏وَوَقْتُ صَلَاةِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ الْأَوْسَطِ وَوَقْتُ صَلَاةِ الصُّبْحِ مِنْ طُلُوعِ الْفَجْرِ مَا لَمْ تَطْلُعْ الشَّمْسُ فَإِذَا طَلَعَتْ الشَّمْسُ فَأَمْسِكْ عَنْ الصَّلَاةِ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ ‏","","",""],[6672,6672,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الَّذِي يَأْتِي امْرَأَتَهُ فِي دُبُرِهَا هِيَ ‏ ‏اللُّوطِيَّةُ ‏ ‏الصُّغْرَى ‏","","",""],[6673,6673,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ الَّذِي يَأْتِي امْرَأَتَهُ فِي دُبُرِهَا ‏ ‏فَقَالَ ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هِيَ ‏ ‏اللُّوطِيَّةُ ‏ ‏الصُّغْرَى ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ وَسَّاجٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏وَهَلْ يَفْعَلُ ذَلِكَ إِلَّا كَافِرٌ ‏","","",""],[6674,6674,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ خَيَّاطٍ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَهِيَ كَفَّارَتُهَا ‏","","",""],[6675,6675,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَهُمْ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ ‏ ‏لَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ وَلَا صَلَاةَ بَعْدَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏حَتَّى تَطْلُعَ الشَّمْسُ وَالْمُؤْمِنُونَ ‏ ‏تَكَافَأُ ‏ ‏دِمَاؤُهُمْ ‏ ‏يَسْعَى ‏ ‏بِذِمَّتِهِمْ ‏ ‏أَدْنَاهُمْ ‏ ‏وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ أَلَا لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ وَلَا ذُو عَهْدٍ فِي عَهْدِهِ ‏","","",""],[6676,6676,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ الْقَطَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا قَالَ فُلَانٌ ابْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏دِعَاوَةَ فِي الْإِسْلَامِ ‏","","",""],[6677,6677,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَآهُ وَعَلَيْهِ ثَوْبَانِ ‏ ‏مُعَصْفَرَانِ ‏ ‏فَقَالَ ‏ ‏هَذِهِ ثِيَابُ الْكُفَّارِ فَلَا تَلْبَسْهَا ‏","","",""],[6678,6678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ يَعْنِي السَّهْمِيَّ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمٌ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا عَلَى الْأَرْضِ رَجُلٌ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ إِلَّا كَفَّرَتْ عَنْهُ مِنْ ذُنُوبِهِ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[6679,6679,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏وَاللَّهِ لَقَدْ زَعَمُوا أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏شَهِدَ بِهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ ثُمَّ إِنْ شَرِبَ فَاجْلِدُوهُ فَإِذَا كَانَ عِنْدَ الرَّابِعَةِ فَاضْرِبُوا عُنُقَهُ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏ائْتُونِي بِرَجُلٍ قَدْ جُلِدَ فِي الْخَمْرِ أَرْبَعَ مَرَّاتٍ فَإِنَّ لَكُمْ عَلَيَّ أَنْ أَضْرِبَ عُنُقَهُ ‏","","",""],[6680,6680,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَظَرَ إِلَى أَعْرَابِيٍّ قَائِمًا فِي الشَّمْسِ وَهُوَ يَخْطُبُ فَقَالَ مَا شَأْنُكَ قَالَ نَذَرْتُ يَا رَسُولَ اللَّهِ أَنْ لَا أَزَالَ فِي الشَّمْسِ حَتَّى تَفْرُغَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ هَذَا نَذْرًا ‏ ‏إِنَّمَا النَّذْرُ مَا ابْتُغِيَ بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[6681,6681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏تَخَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفْرَةٍ سَافَرْنَاهَا فَأَدْرَكَنَا وَقَدْ أَرْهَقَتْنَا صَلَاةُ الْعَصْرِ وَنَحْنُ نَتَوَضَّأُ فَجَعَلْنَا نَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى بِأَعْلَى صَوْتِهِ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[6682,6682,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ لَبِسَ خَاتَمًا مِنْ ذَهَبٍ فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّهُ كَرِهَهُ فَطَرَحَهُ ثُمَّ لَبِسَ خَاتَمًا مِنْ حَدِيدٍ فَقَالَ ‏ ‏هَذَا أَخْبَثُ وَأَخْبَثُ فَطَرَحَهُ ثُمَّ لَبِسَ خَاتَمًا مِنْ ‏ ‏وَرِقٍ ‏ ‏فَسَكَتَ عَنْهُ ‏","","",""],[6683,6683,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي الرُّكْنُ يَوْمَ الْقِيَامَةِ أَعْظَمَ مِنْ ‏ ‏أَبِي قُبَيْسٍ ‏ ‏لَهُ لِسَانٌ وَشَفَتَانِ ‏","","",""],[6684,6684,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ فَيَّاضٍ ‏ ‏عَنْ ‏ ‏أَبِي عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْتَنِبُوا مِنْ الْأَوْعِيَةِ ‏ ‏الدُّبَّاءَ ‏ ‏وَالْمُزَفَّتَ ‏ ‏وَالْحَنْتَمَ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏وَذَكَرَ أَشْيَاءَ ‏ ‏قَالَ فَقَالَ لَهُ أَعْرَابِيٌّ لَا ‏ ‏ظُرُوفَ ‏ ‏لَنَا فَقَالَ اشْرَبُوا مَا حَلَّ وَلَا تَسْكَرُوا أَعَدْتُهُ عَلَى ‏ ‏شَرِيكٍ ‏ ‏فَقَالَ اشْرَبُوا وَلَا تَشْرَبُوا مُسْكِرًا وَلَا تَسْكَرُوا ‏","","",""],[6685,6685,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ سِيمِينْ كُوشَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَكُونُ ‏ ‏فِتْنَةٌ ‏ ‏تَسْتَنْظِفُ ‏ ‏الْعَرَبَ ‏ ‏قَتْلَاهَا فِي النَّارِ اللِّسَانُ فِيهَا أَشَدُّ مِنْ وَقْعِ السَّيْفِ ‏","","",""],[6686,6686,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا كَالْمُوَدِّعِ فَقَالَ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏النَّبِيُّ الْأُمِّيُّ أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏النَّبِيُّ الْأُمِّيُّ ثَلَاثًا وَلَا نَبِيَّ بَعْدِي أُوتِيتُ فَوَاتِحَ الْكَلِمِ وَجَوَامِعَهُ وَخَوَاتِمَهُ وَعَلِمْتُ كَمْ خَزَنَةُ النَّارِ وَحَمَلَةُ الْعَرْشِ وَتُجُوِّزَ بِي وَعُوفِيتُ وَعُوفِيَتْ أُمَّتِي فَاسْمَعُوا وَأَطِيعُوا مَا دُمْتُ فِيكُمْ فَإِذَا ذُهِبَ بِي فَعَلَيْكُمْ بِكِتَابِ اللَّهِ أَحِلُّوا حَلَالَهُ وَحَرِّمُوا حَرَامَهُ ‏","","",""],[6687,6687,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَعَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6688,6688,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6689,6689,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعْنَةُ اللَّهِ عَلَى الرَّاشِي وَالْمُرْتَشِي ‏","","",""],[6690,6690,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ ‏","","",""],[6691,6691,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏فَذَكَرُوا ‏ ‏الرِّيَاءَ ‏ ‏فَقَالَ رَجُلٌ ‏ ‏يُكْنَى ‏ ‏بِأَبِي يَزِيدَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏سَمَّعَ ‏ ‏النَّاسَ بِعَمَلِهِ ‏ ‏سَمَّعَ ‏ ‏اللَّهُ بِهِ سَامِعَ خَلْقِهِ يَوْمَ الْقِيَامَةِ فَحَقَّرَهُ وَصَغَّرَهُ ‏","","",""],[6692,6692,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ خَبَّابٍ أَبِي الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِكْرِمَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ حَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ ذَكَرُوا الْفِتْنَةَ ‏ ‏أَوْ ذُكِرَتْ عِنْدَهُ ‏ ‏قَالَ إِذَا رَأَيْتَ النَّاسَ قَدْ ‏ ‏مَرِجَتْ ‏ ‏عُهُودُهُمْ وَخَفَّتْ أَمَانَاتُهُمْ وَكَانُوا هَكَذَا وَشَبَّكَ بَيْنَ أَصَابِعِهِ قَالَ فَقُمْتُ إِلَيْهِ فَقُلْتُ لَهُ كَيْفَ أَفْعَلُ عِنْدَ ذَلِكَ جَعَلَنِي اللَّهُ فِدَاكَ قَالَ ‏ ‏الْزَمْ بَيْتَكَ وَامْلِكْ عَلَيْكَ لِسَانَكَ وَخُذْ مَا تَعْرِفُ وَدَعْ مَا تُنْكِرُ وَعَلَيْكَ بِأَمْرِ خَاصَّةِ نَفْسِكَ وَدَعْ عَنْكَ أَمْرَ الْعَامَّةِ ‏","","",""],[6693,6693,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَامَ مَنْ صَامَ الْأَبَدَ ‏","","",""],[6694,6694,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ نَتْفِ الشَّيْبِ وَقَالَ إِنَّهُ نُورُ الْإِسْلَامِ ‏","","",""],[6695,6695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْأَخْنَسِ أَبُو مَالِكٍ الْأَزْدِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏نَذْرَ ‏ ‏وَلَا يَمِينَ فِيمَا لَا يَمْلِكُ ابْنُ ‏ ‏آدَمَ ‏ ‏وَلَا فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ وَلَا قَطِيعَةِ رَحِمٍ فَمَنْ حَلَفَ عَلَى يَمِينٍ فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا فَلْيَدَعْهَا وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ فَإِنَّ تَرْكَهَا كَفَّارَتُهَا ‏","","",""],[6696,6696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْبَيْعِ ‏ ‏وَالِاشْتِرَاءِ فِي الْمَسْجِدِ ‏","","",""],[6697,6697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏لَمَّا فُتِحَتْ ‏ ‏مَكَّةُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُفُّوا السِّلَاحَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏يَحْيَى ‏ ‏وَيَزِيدَ ‏ ‏وَقَالَ فِيهِ ‏ ‏وَأَوْفُوا ‏ ‏بِحِلْفِ ‏ ‏الْجَاهِلِيَّةِ فَإِنَّ الْإِسْلَامَ لَمْ يَزِدْهُ إِلَّا شِدَّةً وَلَا تُحْدِثُوا ‏ ‏حِلْفًا ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[6698,6698,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا أَيُّوبَ الْأَزْدِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَمْ يَرْفَعْهُ مَرَّتَيْنِ قَالَ وَسَأَلْتُهُ الثَّالِثَةَ ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتُ صَلَاةِ الظُّهْرِ مَا لَمْ يَحْضُرْ الْعَصْرُ وَوَقْتُ صَلَاةِ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ وَوَقْتُ صَلَاةِ الْمَغْرِبِ مَا لَمْ يَسْقُطْ نُورُ ‏ ‏الشَّفَقِ ‏ ‏وَوَقْتُ صَلَاةِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ وَوَقْتُ صَلَاةِ الْفَجْرِ مَا لَمْ تَطْلُعْ الشَّمْسُ ‏","","",""],[6699,6699,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَامِرُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَسْتَخْلِصُ رَجُلًا مِنْ أُمَّتِي عَلَى رُءُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ فَيَنْشُرُ عَلَيْهِ تِسْعَةً وَتِسْعِينَ ‏ ‏سِجِلًّا ‏ ‏كُلُّ ‏ ‏سِجِلٍّ ‏ ‏مَدَّ الْبَصَرِ ثُمَّ يَقُولُ لَهُ ‏ ‏أَتُنْكِرُ مِنْ هَذَا شَيْئًا أَظَلَمَتْكَ كَتَبَتِي الْحَافِظُونَ قَالَ لَا يَا رَبِّ فَيَقُولُ أَلَكَ عُذْرٌ أَوْ حَسَنَةٌ فَيُبْهَتُ الرَّجُلُ فَيَقُولُ لَا يَا رَبِّ فَيَقُولُ بَلَى إِنَّ لَكَ عِنْدَنَا حَسَنَةً وَاحِدَةً لَا ظُلْمَ الْيَوْمَ عَلَيْكَ فَتُخْرَجُ لَهُ بِطَاقَةٌ فِيهَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فَيَقُولُ أَحْضِرُوهُ فَيَقُولُ يَا رَبِّ مَا هَذِهِ الْبِطَاقَةُ مَعَ هَذِهِ ‏ ‏السِّجِلَّاتِ ‏ ‏فَيُقَالُ إِنَّكَ لَا تُظْلَمُ قَالَ فَتُوضَعُ ‏ ‏السِّجِلَّاتُ ‏ ‏فِي كَفَّةٍ قَالَ ‏ ‏فَطَاشَتْ ‏ ‏السِّجِلَّاتُ ‏ ‏وَثَقُلَتْ الْبِطَاقَةُ وَلَا يَثْقُلُ شَيْءٌ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏","","",""],[6700,6700,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا يَدْخُلَنَّ رَجُلٌ عَلَى ‏ ‏مُغِيبَةٍ ‏ ‏إِلَّا وَمَعَهُ غَيْرُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏فَمَا دَخَلْتُ بَعْدَ ذَلِكَ الْمَقَامِ عَلَى ‏ ‏مُغِيبَةٍ ‏ ‏إِلَّا وَمَعِي وَاحِدٌ أَوْ اثْنَانِ ‏","","",""],[6701,6701,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَوْذَبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرُ بْنُ عَبْدِ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَقْسِمَ غَنِيمَةً ‏ ‏أَمَرَ ‏ ‏بِلَالًا ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَنَادَى ثَلَاثًا فَأَتَى رَجُلٌ ‏ ‏بِزِمَامٍ ‏ ‏مِنْ شَعَرٍ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَنْ قَسَمَ الْغَنِيمَةَ فَقَالَ يَا رَسُولَ اللَّهِ هَذِهِ مِنْ غَنِيمَةٍ كُنْتُ أَصَبْتُهَا قَالَ أَمَا سَمِعْتَ ‏ ‏بِلَالًا ‏ ‏يُنَادِي ثَلَاثًا قَالَ نَعَمْ قَالَ فَمَا مَنَعَكَ أَنْ تَأْتِيَنِي بِهِ ‏ ‏فَاعْتَلَّ ‏ ‏لَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَنْ أَقْبَلَهُ حَتَّى تَكُونَ أَنْتَ الَّذِي ‏ ‏تُوَافِينِي بِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[6702,6702,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏يَقُولُ إِنَّ اللَّهَ وَرَسُولَهُ ‏ ‏حَرَّمَ بَيْعَ الْخَمْرِ وَالْمَيْتَةَ وَالْخِنْزِيرَ فَقِيلَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ شُحُومَ الْمَيْتَةِ فَإِنَّهُ يُدْهَنُ بِهَا السُّفُنُ وَيُدْهَنُ بِهَا الْجُلُودُ وَيَسْتَصْبِحُ بِهَا النَّاسُ فَقَالَ لَا هِيَ حَرَامٌ ثُمَّ قَالَ قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏إِنَّ اللَّهَ لَمَّا حَرَّمَ عَلَيْهِمْ الشُّحُومَ جَمَلُوهَا ثُمَّ بَاعُوهَا وَأَكَلُوا أَثْمَانَهَا ‏","","",""],[6703,6703,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يُصَافِحُ النِّسَاءَ فِي الْبَيْعَةِ ‏","","",""],[6704,6704,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِرَجُلٍ أَنْ يُفَرِّقَ بَيْنَ اثْنَيْنِ إِلَّا بِإِذْنِهِمَا ‏","","",""],[6705,6705,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏رَجَاءٌ أَبُو يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏مُسَافِعُ بْنُ شَيْبَةَ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏فَأَنْشُدُ بِاللَّهِ ثَلَاثًا وَوَضَعَ إِصْبَعَهُ فِي أُذُنَيْهِ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏إِنَّ الرُّكْنَ ‏ ‏وَالْمَقَامَ ‏ ‏يَاقُوتَتَانِ مِنْ يَاقُوتِ الْجَنَّةِ طَمَسَ اللَّهُ عَزَّ وَجَلَّ نُورَهُمَا وَلَوْلَا أَنَّ اللَّهَ طَمَسَ نُورَهُمَا ‏ ‏لَأَضَاءَتَا مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ‏","","",""],[6706,6706,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ أَعْرَابِيًّا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ لِي مَالًا وَوَالِدًا وَإِنَّ وَالِدِي يُرِيدُ أَنْ ‏ ‏يَجْتَاحَ ‏ ‏مَالِي قَالَ ‏ ‏أَنْتَ وَمَالُكَ لِوَالِدِكَ إِنَّ أَوْلَادَكُمْ مِنْ أَطْيَبِ كَسْبِكُمْ فَكُلُوا مِنْ كَسْبِ أَوْلَادِكُمْ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏بَلَغَنِي أَنَّ ‏ ‏حَبِيبًا الْمُعَلِّمَ ‏ ‏يُقَالُ لَهُ ‏ ‏حَبِيبُ بْنُ أَبِي بَقِيَّةَ ‏","","",""],[6707,6707,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَحْضُرُ الْجُمُعَةَ ثَلَاثَةٌ فَرَجُلٌ حَضَرَهَا ‏ ‏يَلْغُو فَذَاكَ حَظُّهُ مِنْهَا وَرَجُلٌ حَضَرَهَا بِدُعَاءٍ فَهُوَ رَجُلٌ دَعَا اللَّهَ عَزَّ وَجَلَّ فَإِنْ شَاءَ أَعْطَاهُ وَإِنْ شَاءَ مَنَعَهُ وَرَجُلٌ حَضَرَهَا بِإِنْصَاتٍ وَسُكُوتٍ وَلَمْ يَتَخَطَّ رَقَبَةَ مُسْلِمٍ وَلَمْ يُؤْذِ أَحَدًا فَهِيَ كَفَّارَةٌ إِلَى الْجُمُعَةِ الَّتِي تَلِيهَا وَزِيَادَةُ ثَلَاثَةِ أَيَّامٍ فَإِنَّ اللَّهَ يَقُولُ ‏ { ‏مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا ‏}","","",""],[6708,6708,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ وَمَنْ شَرِبَ الثَّانِيَةَ فَاجْلِدُوهُ ثُمَّ إِنْ شَرِبَ الثَّالِثَةَ فَاجْلِدُوهُ ثُمَّ إِنْ شَرِبَ الرَّابِعَةَ فَاقْتُلُوهُ ‏","","",""],[6709,6709,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَكْبَرَ الْكَبَائِرِ ‏ ‏عُقُوقُ ‏ ‏الْوَالِدَيْنِ قَالَ قِيلَ وَمَا ‏ ‏عُقُوقُ ‏ ‏الْوَالِدَيْنِ قَالَ يَسُبُّ الرَّجُلُ الرَّجُلَ فَيَسُبُّ أَبَاهُ وَيَسُبُّ أُمَّهُ فَيَسُبُّ أُمَّهُ ‏","","",""],[6710,6710,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَدَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ قَالَ فِي يَوْمٍ مِائَتَيْ مَرَّةٍ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ لَمْ يَسْبِقْهُ أَحَدٌ كَانَ قَبْلَهُ وَلَمْ يُدْرِكْهُ أَحَدٌ كَانَ بَعْدَهُ إِلَّا بِأَفْضَلَ مِنْ عَمَلِهِ ‏ ‏يَعْنِي إِلَّا مَنْ عَمِلَ بِأَفْضَلَ مِنْ عَمَلِهِ ‏","","",""],[6711,6711,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏قَالَ ‏ ‏أَقْبَلَ ‏ ‏أَبُو كَبْشَةَ السَّلُولِيُّ ‏ ‏وَنَحْنُ فِي الْمَسْجِدِ فَقَامَ إِلَيْهِ ‏ ‏مَكْحُولٌ ‏ ‏وَابْنُ أَبِي زَكَرِيَّا ‏ ‏وَأَبُو بَحْرِيَّةَ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَلِّغُوا عَنِّي وَلَوْ آيَةً وَحَدِّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[6712,6712,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرَّاكِبُ شَيْطَانٌ وَالرَّاكِبَانِ شَيْطَانَانِ وَالثَّلَاثَةُ رَكْبٌ ‏","","",""],[6713,6713,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَجَاءُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسَافِعُ بْنُ شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏وَأَدْخَلَ إِصْبَعَيْهِ فِي أُذُنَيْهِ ‏ ‏لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْحَجَرَ ‏ ‏وَالْمَقَامَ ‏ ‏يَاقُوتَتَانِ مِنْ يَاقُوتِ الْجَنَّةِ ‏ ‏طَمَسَ ‏ ‏اللَّهُ نُورَهُمَا لَوْلَا ذَلِكَ لَأَضَاءَتَا مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏ ‏أَوْ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ‏ ‏كَذَا قَالَ ‏ ‏يُونُسُ ‏ ‏رَجَاءُ بْنُ يَحْيَى ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏رَجَاءُ أَبُو يَحْيَى ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏و حَدَّثَنَاه ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَجَاءُ بْنُ صُبَيْحٍ أَبُو يَحْيَى الْحَرَشِيُّ ‏ ‏وَالصَّوَابُ ‏ ‏أَبُو يَحْيَى ‏ ‏كَمَا قَالَ ‏ ‏عَفَّانُ ‏ ‏وهُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَوَارِيرِيُّ عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏رَجَاءُ أَبُو يَحْيَى ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[6714,6714,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عَلِيِّ بْنِ رَبَاحٍ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ النَّارِ كُلُّ ‏ ‏جَعْظَرِيٍّ ‏ ‏جَوَّاظٍ ‏ ‏مُسْتَكْبِرٍ ‏ ‏جَمَّاعٍ ‏ ‏مَنَّاعٍ ‏ ‏وَأَهْلُ الْجَنَّةِ الضُّعَفَاءُ الْمَغْلُوبُونَ ‏","","",""],[6715,6715,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏قَرَنَ ‏ ‏خَشْيَةَ أَنْ يُصَدَّ عَنْ ‏ ‏الْبَيْتِ ‏ ‏وَقَالَ ‏ ‏إِنْ لَمْ تَكُنْ حَجَّةٌ فَعُمْرَةٌ ‏","","",""],[6716,6716,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ عَبْدِ اللَّهِ بْنِ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ عَامَ الْفَتْحِ عَلَى دَرَجَةِ ‏ ‏الْكَعْبَةِ ‏ ‏فَكَانَ فِيمَا قَالَ بَعْدَ أَنْ أَثْنَى عَلَى اللَّهِ أَنْ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏كُلُّ ‏ ‏حِلْفٍ ‏ ‏كَانَ فِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الْإِسْلَامُ إِلَّا شِدَّةً وَلَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ وَلَا هِجْرَةَ بَعْدَ الْفَتْحِ يَدُ الْمُسْلِمِينَ وَاحِدَةٌ عَلَى مَنْ سِوَاهُمْ ‏ ‏تَتَكَافَأُ ‏ ‏دِمَاؤُهُمْ وَلَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ ‏ ‏وَدِيَةُ ‏ ‏الْكَافِرِ كَنِصْفِ ‏ ‏دِيَةِ ‏ ‏الْمُسْلِمِ أَلَا وَلَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ وَلَا ‏ ‏جَنَبَ ‏ ‏وَلَا ‏ ‏جَلَبَ ‏ ‏وَتُؤْخَذُ ‏ ‏صَدَقَاتُهُمْ ‏ ‏فِي دِيَارِهِمْ ‏ ‏يُجِيرُ ‏ ‏عَلَى الْمُسْلِمِينَ ‏ ‏أَدْنَاهُمْ ‏ ‏وَيَرُدُّ عَلَى الْمُسْلِمِينَ أَقْصَاهُمْ ثُمَّ نَزَلَ ‏ ‏وَقَالَ ‏ ‏حُسَيْنٌ ‏ ‏إِنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[6717,6717,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي ‏ ‏الْمَوَاضِحِ ‏ ‏خَمْسٌ خَمْسٌ مِنْ الْإِبِلِ وَالْأَصَابِعُ سَوَاءٌ كُلُّهُنَّ عَشْرٌ عَشْرٌ مِنْ الْإِبِلِ ‏","","",""],[6718,6718,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَقْتُولُ دُونَ مَالِهِ شَهِيدٌ ‏","","",""],[6719,6719,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ أَبُو عَمْرٍو الْجَزَرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي عَبْلَةَ الْعُقَيْلِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قَالَ الْتَقَى ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَلَى ‏ ‏الْمَرْوَةِ ‏ ‏فَتَحَدَّثَا ثُمَّ مَضَى ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏وَبَقِيَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَبْكِي فَقَالَ لَهُ رَجُلٌ مَا ‏ ‏يُبْكِيكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ هَذَا ‏ ‏يَعْنِي ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏زَعَمَ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ كِبْرٍ أَكَبَّهُ اللَّهُ عَلَى وَجْهِهِ فِي النَّارِ ‏","","",""],[6720,6720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ بْنُ بَكْرِ بْنِ خُنَيْسٍ أَبُو الْجَهْمِ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏ثُمَّ ‏ ‏خِدَاجٌ ‏ ‏ثُمَّ ‏ ‏خِدَاجٌ ‏","","",""],[6721,6721,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عَلِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَدْرُونَ مَنْ الْمُسْلِمُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ قَالَ تَدْرُونَ مَنْ الْمُؤْمِنُ قَالُوا اللَّهُ ‏ ‏يَعْنِي وَرَسُولُهُ أَعْلَمُ قَالَ مَنْ أَمِنَهُ الْمُؤْمِنُونَ عَلَى أَنْفُسِهِمْ وَأَمْوَالِهِمْ وَالْمُهَاجِرُ مَنْ هَجَرَ السُّوءَ فَاجْتَنَبَهُ ‏","","",""],[6722,6722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏دُوَيْدٌ الْخُرَاسَانِيُّ ‏ ‏وَالزُّبَيْرُ بْنُ عَدِيٍّ ‏ ‏قَاعِدٌ مَعَهُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نَسْمَعُ مِنْكَ أَحَادِيثَ لَا نَحْفَظُهَا أَفَلَا نَكْتُبُهَا قَالَ بَلَى فَاكْتُبُوهَا ‏","","",""],[6723,6723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْمُثَنَّى بْنِ الصَّبَّاحِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُفْرٌ بِاللَّهِ ‏ ‏تَبَرُّؤٌ ‏ ‏مِنْ نَسَبٍ وَإِنْ دَقَّ أَوْ ادِّعَاءٌ إِلَى نَسَبٍ لَا يُعْرَفُ ‏","","",""],[6724,6724,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَسْمَعُ مِنْكَ أَشْيَاءَ أَفَأَكْتُبُهَا قَالَ نَعَمْ قُلْتُ فِي الْغَضَبِ وَالرِّضَا قَالَ ‏ ‏نَعَمْ فَإِنِّي لَا أَقُولُ فِيهِمَا إِلَّا حَقًّا ‏","","",""],[6725,6725,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏قَالَ ‏ ‏يَعْنِي ‏ ‏عَبْدَ الْوَهَّابِ ‏ ‏وَقَدْ سَمِعْتُهُ مِنْهُ ‏ ‏يَعْنِي ‏ ‏حُسَيْنًا ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْفَتِلُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَرَأَيْتُهُ ‏ ‏يُصَلِّي حَافِيًا وَمُنْتَعِلًا وَرَأَيْتُهُ يَصُومُ فِي السَّفَرِ وَيُفْطِرُ وَرَأَيْتُهُ يَشْرَبُ قَاعِدًا وَقَائِمًا ‏","","",""],[6726,6726,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَيْسَ لِي مَالٌ وَلِي يَتِيمٌ فَقَالَ ‏ ‏كُلْ ‏ ‏مِنْ مَالِ يَتِيمِكَ غَيْرَ مُسْرِفٍ وَلَا ‏ ‏مُبَذِّرٍ ‏ ‏وَلَا ‏ ‏مُتَأَثِّلٍ ‏ ‏مَالًا وَمِنْ غَيْرِ أَنْ تَقِيَ مَالَكَ ‏ ‏أَوْ قَالَ تَفْدِيَ مَالَكَ بِمَالِهِ شَكَّ ‏ ‏حُسَيْنٌ ‏","","",""],[6727,6727,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ بْنُ حُمَيْدٍ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏فِي كَمْ تَقْرَأُ الْقُرْآنَ قَالَ قُلْتُ فِي يَوْمِي وَلَيْلَتِي قَالَ فَقَالَ لِي ارْقُدْ وَصَلِّ وَارْقُدْ وَاقْرَأْهُ فِي كُلِّ شَهْرٍ قَالَ فَمَا زِلْتُ أُنَاقِصُهُ وَيُنَاقِصُنِي إِلَى أَنْ قَالَ اقْرَأْهُ فِي كُلِّ سَبْعِ لَيَالٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ أَفْهَمْ وَسَقَطَتْ عَلَيَّ كَلِمَةٌ ‏ ‏قَالَ ثُمَّ قَالَ قُلْتُ إِنِّي أَصُومُ وَلَا أُفْطِرُ قَالَ فَقَالَ لِي صُمْ وَأَفْطِرْ وَصُمْ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ فَمَا زِلْتُ أُنَاقِصُهُ وَيُنَاقِصُنِي حَتَّى قَالَ ‏ ‏صُمْ أَحَبَّ الصِّيَامِ إِلَى اللَّهِ عَزَّ وَجَلَّ صِيَامَ ‏ ‏دَاوُدَ ‏ ‏صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏لَأَنْ أَكُونَ قَبِلْتُ رُخْصَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي حُمْرُ النَّعَمِ ‏ ‏حَسِبْتُهُ شَكَّ ‏ ‏عَبِيدَةُ ‏","","",""],[6728,6728,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏جَلَبَ ‏ ‏وَلَا ‏ ‏جَنَبَ ‏ ‏وَلَا تُؤْخَذُ صَدَقَاتُهُمْ إِلَّا فِي دُورِهِمْ ‏","","",""],[6729,6729,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سُفْيَانَ الْحَرَشِيُّ ‏ ‏وَكَانَ ثِقَةً فِيمَا ذَكَرَ أَهْلُ بِلَادِهِ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ جُبَيْرٍ ‏ ‏مَوْلَى ‏ ‏ثَقِيفٍ ‏ ‏وَكَانَ ‏ ‏مُسْلِمٌ ‏ ‏رَجُلًا يُؤْخَذُ عَنْهُ وَقَدْ أَدْرَكَ ‏ ‏وَسَمِعَ عَنْ ‏ ‏عَمْرِو بْنِ حُرَيْشٍ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏إِنَّا بِأَرْضٍ لَسْنَا نَجِدُ بِهَا الدِّينَارَ وَالدِّرْهَمَ وَإِنَّمَا أَمْوَالُنَا الْمَوَاشِي فَنَحْنُ نَتَبَايَعُهَا بَيْنَنَا فَنَبْتَاعُ الْبَقَرَةَ بِالشَّاةِ نَظِرَةً إِلَى أَجَلٍ وَالْبَعِيرَ بِالْبَقَرَاتِ وَالْفَرَسَ ‏ ‏بِالْأَبَاعِرِ ‏ ‏كُلُّ ذَلِكَ إِلَى أَجَلٍ فَهَلْ عَلَيْنَا فِي ذَلِكَ مِنْ بَأْسٍ فَقَالَ عَلَى الْخَبِيرِ سَقَطْتَ أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَبْعَثَ جَيْشًا عَلَى إِبِلٍ كَانَتْ عِنْدِي قَالَ فَحَمَلْتُ النَّاسَ عَلَيْهَا حَتَّى نَفِدَتْ الْإِبِلُ وَبَقِيَتْ بَقِيَّةٌ مِنْ النَّاسِ قَالَ فَقُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ الْإِبِلُ قَدْ نَفِدَتْ وَقَدْ بَقِيَتْ بَقِيَّةٌ مِنْ النَّاسِ لَا ظَهْرَ لَهُمْ قَالَ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْتَعْ عَلَيْنَا إِبِلًا ‏ ‏بِقَلَائِصَ ‏ ‏مِنْ إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏إِلَى مَحِلِّهَا حَتَّى نُنَفِّذَ هَذَا الْبَعْثَ قَالَ فَكُنْتُ أَبْتَاعُ الْبَعِيرَ ‏ ‏بِالْقَلُوصَيْنِ ‏ ‏وَالثَّلَاثِ مِنْ إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏إِلَى مَحِلِّهَا حَتَّى نَفَّذْتُ ذَلِكَ الْبَعْثَ قَالَ فَلَمَّا حَلَّتْ ‏ ‏الصَّدَقَةُ ‏ ‏أَدَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[6730,6730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ ذَكَرَ ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏عَقْلِ ‏ ‏الْجَنِينِ إِذَا كَانَ فِي بَطْنِ أُمِّهِ ‏ ‏بِغُرَّةٍ ‏ ‏عَبْدٍ أَوْ أَمَةٍ فَقَضَى بِذَلِكَ فِي امْرَأَةِ ‏ ‏حَمَلِ بْنِ مَالِكِ بْنِ النَّابِغَةِ الْهُذَلِيِّ ‏","","",""],[6731,6731,"","","‏ ‏وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[6732,6732,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ يَعْنِي مُحَمَّدًا ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[6733,6733,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَلَدِ ‏ ‏الْمُتَلَاعِنَيْنِ ‏ ‏أَنَّهُ يَرِثُ أُمَّهُ وَتَرِثُهُ أُمُّهُ وَمَنْ ‏ ‏قَفَاهَا ‏ ‏بِهِ جُلِدَ ثَمَانِينَ وَمَنْ دَعَاهُ وَلَدَ زِنًا جُلِدَ ثَمَانِينَ ‏","","",""],[6734,6734,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَلْعَنُ الرَّجُلُ أَبَوَيْهِ قَالَ يَسُبُّ الرَّجُلُ الرَّجُلَ فَيَسُبُّ أَبَاهُ وَيَسُبُّ الرَّجُلُ أُمَّهُ فَيَسُبُّ أُمَّهُ ‏","","",""],[6735,6735,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ الْمُطَّلِبِ الْمَخْزُومِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ السَّهْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَسَنِ بْنِ حَسَنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ طَلْحَةَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[6736,6736,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِى ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عِيسَى بْنُ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏وَقَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ عَلَى رَاحِلَتِهِ ‏ ‏فَطَفِقَ ‏ ‏يَسْأَلُونَهُ فَيَقُولُ الْقَائِلُ مِنْهُمْ يَا رَسُولَ اللَّهِ إِنِّي لَمْ أَكُنْ أَشْعُرُ أَنَّ الرَّمْيَ قَبْلَ النَّحْرِ فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْمِ وَلَا حَرَجَ ‏ ‏وَطَفِقَ ‏ ‏آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَمْ أَشْعُرْ أَنَّ النَّحْرَ قَبْلَ الْحَلْقِ فَحَلَقْتُ قَبْلَ أَنْ أَنْحَرَ فَيَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْحَرْ وَلَا حَرَجَ قَالَ ‏ ‏فَمَا سَمِعْتُهُ يَوْمَئِذٍ يُسْأَلُ عَنْ أَمْرٍ مِمَّا ‏ ‏يَنْسَى الْإِنْسَانُ أَوْ يَجْهَلُ مِنْ تَقْدِيمِ الْأُمُورِ بَعْضِهَا قَبْلَ بَعْضٍ وَأَشْبَاهِهَا إِلَّا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْعَلْهُ وَلَا حَرَجَ ‏","","",""],[6737,6737,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏فَذَكَرَ حَدِيثًا قَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏وَذَكَرَ ‏ ‏عَمْرُو بْنُ شُعَيْبِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ مُؤْمِنًا مُتَعَمِّدًا فَإِنَّهُ يُدْفَعُ إِلَى أَوْلِيَاءِ الْقَتِيلِ فَإِنْ شَاءُوا قَتَلُوا وَإِنْ شَاءُوا أَخَذُوا ‏ ‏الدِّيَةَ ‏ ‏وَهِيَ ثَلَاثُونَ ‏ ‏حِقَّةً ‏ ‏وَثَلَاثُونَ ‏ ‏جَذَعَةً ‏ ‏وَأَرْبَعُونَ ‏ ‏خَلِفَةً ‏ ‏فَذَلِكَ ‏ ‏عَقْلُ ‏ ‏الْعَمْدِ وَمَا صَالَحُوا عَلَيْهِ مِنْ شَيْءٍ فَهُوَ لَهُمْ وَذَلِكَ شَدِيدُ ‏ ‏الْعَقْلِ ‏ ‏وَعَقْلُ ‏ ‏شِبْهِ الْعَمْدِ مُغَلَّظَةٌ مِثْلُ ‏ ‏عَقْلِ ‏ ‏الْعَمْدِ وَلَا يُقْتَلُ صَاحِبُهُ وَذَلِكَ أَنْ يَنْزِغَ الشَّيْطَانُ بَيْنَ النَّاسِ فَتَكُونَ دِمَاءٌ فِي غَيْرِ ‏ ‏ضَغِينَةٍ ‏ ‏وَلَا حَمْلِ سِلَاحٍ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَعْنِي مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَلَا ‏ ‏رَصَدَ ‏ ‏بِطَرِيقٍ فَمَنْ قُتِلَ عَلَى غَيْرِ ذَلِكَ فَهُوَ شِبْهُ الْعَمْدِ ‏ ‏وَعَقْلُهُ ‏ ‏مُغَلَّظَةٌ ‏ ‏وَلَا يُقْتَلُ صَاحِبُهُ وَهُوَ بِالشَّهْرِ الْحَرَامِ وَلِلْحُرْمَةِ وَلِلْجَارِ وَمَنْ قُتِلَ خَطَأً ‏ ‏فَدِيَتُهُ ‏ ‏مِائَةٌ مِنْ الْإِبِلِ ثَلَاثُونَ ‏ ‏ابْنَةُ مَخَاضٍ ‏ ‏وَثَلَاثُونَ ‏ ‏ابْنَةُ لَبُونٍ ‏ ‏وَثَلَاثُونَ ‏ ‏حِقَّةٌ ‏ ‏وَعَشْرُ ‏ ‏بَكَارَةٍ ‏ ‏بَنِي لَبُونٍ ‏ ‏ذُكُورٍ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقِيمُهَا عَلَى أَهْلِ الْقُرَى أَرْبَعَ مِائَةِ دِينَارٍ أَوْ عِدْلَهَا مِنْ ‏ ‏الْوَرِقِ ‏ ‏وَكَانَ يُقِيمُهَا عَلَى أَثْمَانِ الْإِبِلِ فَإِذَا غَلَتْ رَفَعَ فِي قِيمَتِهَا وَإِذَا هَانَتْ نَقَصَ مِنْ قِيمَتِهَا عَلَى عَهْدِ الزَّمَانِ مَا كَانَ فَبَلَغَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ أَرْبَعِ مِائَةِ دِينَارٍ إِلَى ثَمَانِ مِائَةِ دِينَارٍ وَعِدْلُهَا مِنْ ‏ ‏الْوَرِقِ ‏ ‏ثَمَانِيَةُ آلَافِ دِرْهَمٍ وَقَضَى أَنَّ مَنْ كَانَ ‏ ‏عَقْلُهُ ‏ ‏عَلَى أَهْلِ الْبَقَرِ فِي الْبَقَرِ مِائَتَيْ بَقَرَةٍ وَقَضَى أَنَّ مَنْ كَانَ ‏ ‏عَقْلُهُ ‏ ‏عَلَى أَهْلِ الشَّاءِ فَأَلْفَيْ شَاةٍ وَقَضَى فِي الْأَنْفِ إِذَا ‏ ‏جُدِعَ ‏ ‏كُلُّهُ ‏ ‏بِالْعَقْلِ ‏ ‏كَامِلًا وَإِذَا ‏ ‏جُدِعَتْ ‏ ‏أَرْنَبَتُهُ ‏ ‏فَنِصْفُ ‏ ‏الْعَقْلِ ‏ ‏وَقَضَى فِي الْعَيْنِ نِصْفَ ‏ ‏الْعَقْلِ ‏ ‏خَمْسِينَ مِنْ الْإِبِلِ أَوْ عِدْلَهَا ذَهَبًا أَوْ ‏ ‏وَرِقًا ‏ ‏أَوْ مِائَةَ بَقَرَةٍ أَوْ أَلْفَ شَاةٍ وَالرِّجْلُ نِصْفُ ‏ ‏الْعَقْلِ ‏ ‏وَالْيَدُ نِصْفُ ‏ ‏الْعَقْلِ ‏ ‏وَالْمَأْمُومَةُ ‏ ‏ثُلُثُ ‏ ‏الْعَقْلِ ‏ ‏ثَلَاثٌ وَثَلَاثُونَ مِنْ الْإِبِلِ أَوْ قِيمَتُهَا مِنْ الذَّهَبِ أَوْ ‏ ‏الْوَرِقِ ‏ ‏أَوْ الْبَقَرِ أَوْ الشَّاءِ ‏ ‏وَالْجَائِفَةُ ‏ ‏ثُلُثُ ‏ ‏الْعَقْلِ ‏ ‏وَالْمُنَقِّلَةُ ‏ ‏خَمْسَ عَشْرَةَ مِنْ الْإِبِلِ ‏ ‏وَالْمُوضِحَةُ ‏ ‏خَمْسٌ مِنْ الْإِبِلِ وَالْأَسْنَانُ خَمْسٌ مِنْ الْإِبِلِ ‏ ‏قَالَ ‏ ‏وَذَكَرَ ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجُلٍ طَعَنَ رَجُلًا بِقَرْنٍ فِي رِجْلِهِ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَقِدْنِي ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَعْجَلْ حَتَّى يَبْرَأَ جُرْحُكَ قَالَ فَأَبَى الرَّجُلُ إِلَّا أَنْ ‏ ‏يَسْتَقِيدَ ‏ ‏فَأَقَادَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُ قَالَ فَعَرِجَ ‏ ‏الْمُسْتَقِيدُ ‏ ‏وَبَرَأَ ‏ ‏الْمُسْتَقَادُ ‏ ‏مِنْهُ فَأَتَى ‏ ‏الْمُسْتَقِيدُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ يَا رَسُولَ اللَّهِ عَرِجْتُ ‏ ‏وَبَرَأَ ‏ ‏صَاحِبِي فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ آمُرْكَ أَلَّا ‏ ‏تَسْتَقِيدَ ‏ ‏حَتَّى ‏ ‏يَبْرَأَ ‏ ‏جُرْحُكَ فَعَصَيْتَنِي فَأَبْعَدَكَ اللَّهُ وَبَطَلَ جُرْحُكَ ثُمَّ أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الرَّجُلِ الَّذِي عَرِجَ مَنْ كَانَ بِهِ جُرْحٌ أَنْ لَا ‏ ‏يَسْتَقِيدَ ‏ ‏حَتَّى ‏ ‏تَبْرَأَ ‏ ‏جِرَاحَتُهُ فَإِذَا ‏ ‏بَرِئَتْ ‏ ‏جِرَاحَتُهُ ‏ ‏اسْتَقَادَ ‏","","",""],[6738,6738,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏سَمِعْتُهُ يُحَدِّثُ ‏ ‏يَعْنِي ‏ ‏أَبَاهُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَجْلِسٍ ‏ ‏أَلَا أُحَدِّثُكُمْ بِأَحَبِّكُمْ إِلَيَّ وَأَقْرَبِكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ ثَلَاثَ مَرَّاتٍ يَقُولُهَا قَالَ قُلْنَا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَقَالَ أَحْسَنُكُمْ أَخْلَاقًا ‏","","",""],[6739,6739,"","","‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏يَحْيَى بْنُ عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ مَا أَكْثَرَ مَا رَأَيْتَ ‏ ‏قُرَيْشًا ‏ ‏أَصَابَتْ مِنْ رَسُولِ اللَّهِ فِيمَا كَانَتْ تُظْهِرُ مِنْ عَدَاوَتِهِ قَالَ حَضَرْتُهُمْ وَقَدْ اجْتَمَعَ أَشْرَافُهُمْ يَوْمًا فِي ‏ ‏الْحِجْرِ ‏ ‏فَذَكَرُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا مَا رَأَيْنَا مِثْلَ مَا صَبَرْنَا عَلَيْهِ مِنْ هَذَا الرَّجُلِ قَطُّ ‏ ‏سَفَّهَ ‏ ‏أَحْلَامَنَا ‏ ‏وَشَتَمَ آبَاءَنَا وَعَابَ دِينَنَا وَفَرَّقَ جَمَاعَتَنَا وَسَبَّ آلِهَتَنَا لَقَدْ صَبَرْنَا مِنْهُ عَلَى أَمْرٍ عَظِيمٍ ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏قَالَ فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ طَلَعَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ يَمْشِي حَتَّى اسْتَلَمَ الرُّكْنَ ثُمَّ مَرَّ بِهِمْ طَائِفًا ‏ ‏بِالْبَيْتِ ‏ ‏فَلَمَّا أَنْ مَرَّ بِهِمْ غَمَزُوهُ بِبَعْضِ مَا يَقُولُ قَالَ فَعَرَفْتُ ذَلِكَ فِي وَجْهِهِ ثُمَّ مَضَى فَلَمَّا مَرَّ بِهِمْ الثَّانِيَةَ غَمَزُوهُ بِمِثْلِهَا فَعَرَفْتُ ذَلِكَ فِي وَجْهِهِ ثُمَّ مَضَى ثُمَّ مَرَّ بِهِمْ الثَّالِثَةَ فَغَمَزُوهُ بِمِثْلِهَا فَقَالَ تَسْمَعُونَ يَا مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏أَمَا وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَقَدْ جِئْتُكُمْ بِالذَّبْحِ فَأَخَذَتْ الْقَوْمَ كَلِمَتُهُ حَتَّى مَا مِنْهُمْ رَجُلٌ إِلَّا كَأَنَّمَا عَلَى رَأْسِهِ طَائِرٌ وَاقِعٌ حَتَّى إِنَّ أَشَدَّهُمْ فِيهِ ‏ ‏وَصَاةً ‏ ‏قَبْلَ ذَلِكَ لَيَرْفَؤُهُ بِأَحْسَنِ مَا يَجِدُ مِنْ الْقَوْلِ حَتَّى إِنَّهُ لَيَقُولُ انْصَرِفْ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏انْصَرِفْ رَاشِدًا فَوَاللَّهِ مَا كُنْتَ جَهُولًا قَالَ فَانْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَ الْغَدُ اجْتَمَعُوا فِي ‏ ‏الْحِجْرِ ‏ ‏وَأَنَا مَعَهُمْ فَقَالَ بَعْضُهُمْ لِبَعْضٍ ذَكَرْتُمْ مَا بَلَغَ مِنْكُمْ وَمَا بَلَغَكُمْ عَنْهُ حَتَّى إِذَا بَادَأَكُمْ بِمَا تَكْرَهُونَ تَرَكْتُمُوهُ فَبَيْنَمَا هُمْ فِي ذَلِكَ إِذْ طَلَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَثَبُوا ‏ ‏إِلَيْهِ ‏ ‏وَثْبَةَ ‏ ‏رَجُلٍ وَاحِدٍ فَأَحَاطُوا بِهِ يَقُولُونَ لَهُ أَنْتَ الَّذِي تَقُولُ كَذَا وَكَذَا لِمَا كَانَ يَبْلُغُهُمْ عَنْهُ مِنْ عَيْبِ آلِهَتِهِمْ وَدِينِهِمْ قَالَ فَيَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ أَنَا الَّذِي أَقُولُ ذَلِكَ قَالَ فَلَقَدْ رَأَيْتُ رَجُلًا مِنْهُمْ أَخَذَ بِمَجْمَعِ رِدَائِهِ قَالَ وَقَامَ ‏ ‏أَبُو بَكْرٍ الصِّدِّيقُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏دُونَهُ يَقُولُ وَهُوَ يَبْكِي ‏ { ‏أَتَقْتُلُونَ رَجُلًا أَنْ يَقُولَ ‏ ‏رَبِّيَ اللَّهُ ‏} ‏ثُمَّ انْصَرَفُوا عَنْهُ فَإِنَّ ذَلِكَ لَأَشَدُّ مَا رَأَيْتُ ‏ ‏قُرَيْشًا ‏ ‏بَلَغَتْ مِنْهُ قَطُّ ‏","","",""],[6740,6740,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ ‏ ‏وَفْدَ هَوَازِنَ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْجِعِرَّانَةِ ‏ ‏وَقَدْ أَسْلَمُوا فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أَصْلٌ وَعَشِيرَةٌ وَقَدْ أَصَابَنَا مِنْ الْبَلَاءِ مَا لَا ‏ ‏يَخْفَى عَلَيْكَ ‏ ‏فَامْنُنْ ‏ ‏عَلَيْنَا ‏ ‏مَنَّ ‏ ‏اللَّهُ عَلَيْكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْنَاؤُكُمْ وَنِسَاؤُكُمْ أَحَبُّ إِلَيْكُمْ أَمْ أَمْوَالُكُمْ قَالُوا يَا رَسُولَ اللَّهِ خَيَّرْتَنَا بَيْنَ أَحْسَابِنَا وَبَيْنَ أَمْوَالِنَا بَلْ تُرَدُّ عَلَيْنَا نِسَاؤُنَا وَأَبْنَاؤُنَا فَهُوَ أَحَبُّ إِلَيْنَا فَقَالَ لَهُمْ أَمَّا مَا كَانَ لِي ‏ ‏وَلِبَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَهُوَ لَكُمْ فَإِذَا صَلَّيْتُ لِلنَّاسِ الظُّهْرَ فَقُومُوا فَقُولُوا إِنَّا نَسْتَشْفِعُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمُسْلِمِينَ وَبِالْمُسْلِمِينَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَبْنَائِنَا وَنِسَائِنَا ‏ ‏فَسَأُعْطِيكُمْ عِنْدَ ذَلِكَ وَأَسْأَلُ لَكُمْ فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاسِ الظُّهْرَ قَامُوا فَتَكَلَّمُوا بِالَّذِي أَمَرَهُمْ بِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا مَا كَانَ لِي ‏ ‏ولِبَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَهُوَ لَكُمْ قَالَ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَمَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَمَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَقْرَعُ بْنُ حَابِسٍ ‏ ‏أَمَّا أَنَا ‏ ‏وَبَنُو تَمِيمٍ ‏ ‏فَلَا وَقَالَ ‏ ‏عُيَيْنَةُ بْنُ حِصْنِ بْنِ حُذَيْفَةَ بْنِ بَدْرٍ ‏ ‏أَمَّا أَنَا ‏ ‏وَبَنُو فَزَارَةَ ‏ ‏فَلَا قَالَ ‏ ‏عَبَّاسُ بْنُ مِرْدَاسٍ ‏ ‏أَمَّا أَنَا ‏ ‏وَبَنُو سُلَيْمٍ ‏ ‏فَلَا قَالَتْ ‏ ‏بَنُو سُلَيْمٍ ‏ ‏لَا مَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ ‏ ‏عَبَّاسٌ ‏ ‏يَا ‏ ‏بَنِي سُلَيْمٍ ‏ ‏وَهَّنْتُمُونِي ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا ‏ ‏مَنْ تَمَسَّكَ مِنْكُمْ بِحَقِّهِ مِنْ هَذَا ‏ ‏السَّبْيِ ‏ ‏فَلَهُ بِكُلِّ إِنْسَانٍ سِتُّ فَرَائِضَ مِنْ أَوَّلِ شَيْءٍ نُصِيبُهُ فَرَدُّوا عَلَى النَّاسِ أَبْنَاءَهُمْ وَنِسَاءَهُمْ ‏","","",""],[6741,6741,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُبَيْدَةَ بْنُ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ أَبِي الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ أَنَا ‏ ‏وَتَلِيدُ بْنُ كِلَابٍ اللَّيْثِيُّ ‏ ‏حَتَّى أَتَيْنَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏مُعَلِّقًا نَعْلَيْهِ بِيَدِهِ فَقُلْنَا لَهُ هَلْ حَضَرْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ يُكَلِّمُهُ ‏ ‏التَّمِيمِيُّ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏قَالَ نَعَمْ أَقْبَلَ رَجُلٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏يُقَالُ لَهُ ‏ ‏ذُو الْخُوَيْصِرَةِ ‏ ‏فَوَقَفَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُعْطِي النَّاسَ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قَدْ رَأَيْتَ مَا صَنَعْتَ فِي هَذَا الْيَوْمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجَلْ فَكَيْفَ رَأَيْتَ قَالَ لَمْ أَرَكَ عَدَلْتَ قَالَ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنْ لَمْ يَكُنْ الْعَدْلُ عِنْدِي فَعِنْدَ مَنْ يَكُونُ فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَا رَسُولَ اللَّهِ أَلَا نَقْتُلُهُ قَالَ لَا ‏ ‏دَعُوهُ فَإِنَّهُ سَيَكُونُ لَهُ ‏ ‏شِيعَةٌ ‏ ‏يَتَعَمَّقُونَ فِي الدِّينِ حَتَّى يَخْرُجُوا مِنْهُ كَمَا يَخْرُجُ السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏يُنْظَرُ فِي ‏ ‏النَّصْلِ ‏ ‏فَلَا يُوجَدُ شَيْءٌ ثُمَّ فِي ‏ ‏الْقِدْحِ ‏ ‏فَلَا يُوجَدُ شَيْءٌ ثُمَّ فِي ‏ ‏الْفُوقِ ‏ ‏فَلَا يُوجَدُ شَيْءٌ سَبَقَ ‏ ‏الْفَرْثَ ‏ ‏وَالدَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏هَذَا اسْمُهُ ‏ ‏مُحَمَّدٌ ‏ ‏ثِقَةٌ ‏ ‏وَأَخُوهُ ‏ ‏سَلَمَةُ بْنُ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏لَمْ يَرْوِ عَنْهُ إِلَّا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏وَلَا نَعْلَمُ خَبَرَهُ ‏ ‏وَمِقْسَمٌ ‏ ‏لَيْسَ بِهِ بَأْسٌ ‏ ‏وَلِهَذَا الْحَدِيثِ طُرُقٌ فِي هَذَا الْمَعْنَى وَطُرُقٌ أُخَرُ فِي هَذَا الْمَعْنَى صِحَاحٌ وَاللَّهُ سُبْحَانَهُ وَتَعَالَى أَعْلَمُ ‏","","",""],[6742,6742,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ وَعَنْ ‏ ‏الْجَلَّالَةِ ‏ ‏وَعَنْ رُكُوبِهَا وَأَكْلِ لُحُومِهَا ‏","","",""],[6743,6743,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآيَاتُ خَرَزَاتٌ مَنْظُومَاتٌ فِي سِلْكٍ ‏ ‏فَإِنْ يُقْطَعْ ‏ ‏السِّلْكُ يَتْبَعْ بَعْضُهَا بَعْضًا ‏","","",""],[6744,6744,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ يَعْنِي ابْنَ عُثْمَانَ الرَّحَبِيَّ ‏ ‏عَنْ ‏ ‏حِبَّانَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مِنْبَرِهِ يَقُولُ ‏ ‏ارْحَمُوا تُرْحَمُوا وَاغْفِرُوا يَغْفِرْ اللَّهُ لَكُمْ وَيْلٌ ‏ ‏لِأَقْمَاعِ ‏ ‏الْقَوْلِ وَيْلٌ لِلْمُصِرِّينَ الَّذِينَ يُصِرُّونَ عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ‏","","",""],[6745,6745,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي ابْنَ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّ ‏ ‏كُلَّ ‏ ‏مُسْتَلْحَقٍ ‏ ‏يُسْتَلْحَقُ ‏ ‏بَعْدَ أَبِيهِ الَّذِي يُدْعَى لَهُ ادَّعَاهُ وَرَثَتُهُ مِنْ بَعْدِهِ فَقَضَى إِنْ كَانَ مِنْ أَمَةٍ يَمْلِكُهَا يَوْمَ أَصَابَهَا فَقَدْ لَحِقَ بِمَنْ اسْتَلْحَقَهُ وَلَيْسَ لَهُ فِيمَا قُسِمَ قَبْلَهُ مِنْ الْمِيرَاثِ شَيْءٌ وَمَا أَدْرَكَ مِنْ مِيرَاثٍ لَمْ يُقْسَمْ فَلَهُ نَصِيبُهُ وَلَا يُلْحَقُ إِذَا كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ أَنْكَرَهُ وَإِنْ كَانَ مِنْ أَمَةٍ لَا يَمْلِكُهَا أَوْ مِنْ حُرَّةٍ عَاهَرَ بِهَا فَإِنَّهُ لَا يُلْحَقُ وَلَا يَرِثُ وَإِنْ كَانَ أَبُوهُ الَّذِي يُدْعَى لَهُ هُوَ الَّذِي ادَّعَاهُ وَهُوَ وَلَدُ زِنًا لِأَهْلِ أُمِّهِ مَنْ كَانُوا حُرَّةً أَوْ أَمَةً ‏","","",""],[6746,6746,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏وَهُوَ جَالِسٌ فِي ‏ ‏الْحِجْرِ ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏إِيَّاكَ ‏ ‏وَالْإِلْحَادَ ‏ ‏فِي ‏ ‏حَرَمِ اللَّهِ ‏ ‏فَإِنِّي أَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُحِلُّهَا وَيَحُلُّ بِهِ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏لَوْ وُزِنَتْ ذُنُوبُهُ بِذُنُوبِ ‏ ‏الثَّقَلَيْنِ ‏ ‏لَوَزَنَتْهَا قَالَ فَانْظُرْ أَنْ لَا تَكُونَ هُوَ يَا ‏ ‏ابْنَ عَمْرٍو ‏ ‏فَإِنَّكَ قَدْ قَرَأْتَ الْكُتُبَ وَصَحِبْتَ الرَّسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَإِنِّي أُشْهِدُكَ أَنَّ هَذَا وَجْهِي إِلَى ‏ ‏الشَّأْمِ ‏ ‏مُجَاهِدًا ‏","","",""],[6747,6747,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ يَعْنِي الْأَشْيَبَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَرَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ { ‏لَهُمْ الْبُشْرَى فِي الْحَيَاةِ الدُّنْيَا ‏} ‏قَالَ الرُّؤْيَا الصَّالِحَةُ يُبَشَّرُهَا الْمُؤْمِنُ هِيَ جُزْءٌ مِنْ تِسْعَةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ فَمَنْ رَأَى ذَلِكَ فَلْيُخْبِرْ بِهَا وَمَنْ رَأَى سِوَى ذَلِكَ فَإِنَّمَا هُوَ مِنْ الشَّيْطَانِ لِيُحْزِنَهُ فَلْيَنْفُثْ ‏ ‏عَنْ يَسَارِهِ ثَلَاثًا وَلْيَسْكُتْ وَلَا يُخْبِرْ بِهَا أَحَدًا ‏","","",""],[6748,6748,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَدَّتْهُ ‏ ‏الطِّيَرَةُ ‏ ‏مِنْ حَاجَةٍ فَقَدْ أَشْرَكَ قَالُوا يَا رَسُولَ اللَّهِ مَا كَفَّارَةُ ذَلِكَ قَالَ أَنْ يَقُولَ أَحَدُهُمْ اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُكَ وَلَا ‏ ‏طَيْرَ ‏ ‏إِلَّا ‏ ‏طَيْرُكَ ‏ ‏وَلَا إِلَهَ غَيْرُكَ ‏","","",""],[6749,6749,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏خَبَرِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ لَمَّا كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُودِيَ أَنْ الصَّلَاةُ جَامِعَةٌ ‏ ‏فَرَكَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ فِي سَجْدَةٍ ثُمَّ ‏ ‏جُلِّيَ ‏ ‏عَنْ الشَّمْسِ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏مَا سَجَدْتُ سُجُودًا قَطُّ أَطْوَلَ مِنْهُ وَلَا رَكَعْتُ رُكُوعًا قَطُّ أَطْوَلَ مِنْهُ ‏","","",""],[6750,6750,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏خَبَرِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ لَمَّا كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُودِيَ أَنَّ الصَّلَاةَ جَامِعَةٌ ‏ ‏فَرَكَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ فِي سَجْدَةٍ ثُمَّ جُلِّيَ عَنْ الشَّمْسِ ‏ ‏فَقَالَتْ ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏مَا سَجَدْتُ سُجُودًا قَطُّ أَطْوَلَ مِنْهُ وَلَا رَكَعْتُ رُكُوعًا قَطُّ كَانَ أَطْوَلَ مِنْهُ ‏","","",""],[6751,6751,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَرْوَاحَ الْمُؤْمِنِينَ لَتَلْتَقِيَانِ عَلَى مَسِيرَةِ يَوْمٍ وَلَيْلَةٍ وَمَا رَأَى وَاحِدٌ مِنْهُمَا صَاحِبَهُ ‏","","",""],[6752,6752,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَأْتِي عَلَى النَّاسِ زَمَانٌ يُغَرْبَلُونَ فِيهِ غَرْبَلَةً يَبْقَى مِنْهُمْ ‏ ‏حُثَالَةٌ ‏ ‏قَدْ ‏ ‏مَرِجَتْ ‏ ‏عُهُودُهُمْ وَأَمَانَاتُهُمْ وَاخْتَلَفُوا فَكَانُوا هَكَذَا وَشَبَّكَ بَيْنَ أَصَابِعِهِ قَالُوا يَا رَسُولَ اللَّهِ فَمَا الْمَخْرَجُ مِنْ ذَلِكَ قَالَ تَأْخُذُونَ مَا تَعْرِفُونَ وَتَدَعُونَ مَا تُنْكِرُونَ وَتُقْبِلُونَ عَلَى أَمْرِ خَاصَّتِكُمْ وَتَدَعُونَ أَمْرَ عَامَّتِكُمْ ‏","","",""],[6753,6753,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ سَعِيدٍ التُّجِيبِيُّ ‏ ‏سَمِعْتُ ‏ ‏أَبَا قَبِيلٍ الْمِصْرِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ يَوْمَ الْجُمُعَةِ أَوْ لَيْلَةَ الْجُمُعَةِ وُقِيَ فِتْنَةَ الْقَبْرِ ‏","","",""],[6754,6754,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏الْمُفَضَّلُ ‏ ‏حَدَّثَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُغْفَرُ لِلشَّهِيدِ كُلُّ ذَنْبٍ إِلَّا الدَّيْنَ ‏","","",""],[6755,6755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ حُجَيْرَةَ الْأَكْبَرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏الْمُسْلِمَ ‏ ‏الْمُسَدِّدَ ‏ ‏لَيُدْرِكُ دَرَجَةَ الصَّوَّامِ ‏ ‏الْقَوَّامِ ‏ ‏بِآيَاتِ اللَّهِ عَزَّ وَجَلَّ لِكَرَمِ ضَرِيبَتِهِ وَحُسْنِ خُلُقِهِ ‏","","",""],[6756,6756,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ وَهُوَ الْحَرَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُخَرِّبُ ‏ ‏الْكَعْبَةَ ‏ ‏ذُو السُّوَيْقَتَيْنِ ‏ ‏مِنْ ‏ ‏الْحَبَشَةِ ‏ ‏وَيَسْلُبُهَا حِلْيَتَهَا وَيُجَرِّدُهَا مِنْ كِسْوَتِهَا وَلَكَأَنِّي أَنْظُرُ إِلَيْهِ ‏ ‏أُصَيْلِعَ ‏ ‏أُفَيْدِعَ ‏ ‏يَضْرِبُ عَلَيْهَا ‏ ‏بِمِسْحَاتِهِ ‏ ‏وَمِعْوَلِهِ ‏","","",""],[6757,6757,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏قَيْصَرَ التُّجِيبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ شَابٌّ فَقَالَ يَا رَسُولَ اللَّهِ أُقَبِّلُ وَأَنَا صَائِمٌ فَقَالَ لَا فَجَاءَ شَيْخٌ فَقَالَ يَا رَسُولَ اللَّهِ أُقَبِّلُ وَأَنَا صَائِمٌ قَالَ نَعَمْ فَنَظَرَ بَعْضُنَا إِلَى بَعْضٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ عَلِمْتُ نَظَرَ بَعْضِكُمْ إِلَى بَعْضٍ ‏ ‏إِنَّ الشَّيْخَ يَمْلِكُ نَفْسَهُ ‏","","",""],[6758,6758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ مَظْلُومًا فَهُوَ شَهِيدٌ ‏","","",""],[6759,6759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَنَى لِلَّهِ مَسْجِدًا بُنِيَ لَهُ بَيْتٌ أَوْسَعُ مِنْهُ فِي الْجَنَّةِ ‏","","",""],[6760,6760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَنَعَ فَضْلَ مَائِهِ أَوْ فَضْلَ كَلَئِهِ مَنْعَهُ اللَّهُ عَزَّ وَجَلَّ فَضْلَهُ ‏","","",""],[6761,6761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏وَحَبِيبٍ الْمُعَلِّمِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَيْسٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏أَحْسِبُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ لِلْمَرْأَةِ أَمْرٌ فِي مَالِهَا إِذَا مَلَكَ زَوْجُهَا عِصْمَتَهَا ‏","","",""],[6762,6762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا قَالَ اللَّهُمَّ اغْفِرْ لِي ‏ ‏وَلِمُحَمَّدٍ ‏ ‏وَحْدَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ حَجَبْتَهَا عَنْ نَاسٍ كَثِيرٍ ‏","","",""],[6763,6763,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا دَخَلَ الصَّلَاةَ فَقَالَ الْحَمْدُ لِلَّهِ وَسَبَّحَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَائِلُهَا فَقَالَ الرَّجُلُ أَنَا قَالَ لَقَدْ ‏ ‏رَأَيْتُ الْمَلَائِكَةَ تَلَقَّى بِهَا بَعْضُهَا بَعْضًا ‏","","",""],[6764,6764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏السَّامُ ‏ ‏عَلَيْكَ وَقَالُوا فِي أَنْفُسِهِمْ ‏ { ‏لَوْلَا يُعَذِّبُنَا اللَّهُ بِمَا نَقُولُ ‏} ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَإِذَا جَاءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ ‏ ‏فَقَرَأَ إِلَى قَوْلِهِ ‏ ‏فَبِئْسَ الْمَصِيرُ ‏}","","",""],[6765,6765,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏وَكَانَ شَاعِرًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْذَنَهُ فِي الْجِهَادِ فَقَالَ أَحَيٌّ وَالِدَاكَ قَالَ نَعَمْ قَالَ فَفِيهِمَا فَجَاهِدْ ‏","","",""],[6766,6766,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يُغَرْبَلَ النَّاسُ غَرْبَلَةً وَتَبْقَى ‏ ‏حُثَالَةٌ ‏ ‏مِنْ النَّاسِ قَدْ ‏ ‏مَرِجَتْ ‏ ‏عُهُودُهُمْ وَأَمَانَاتُهُمْ وَكَانُوا هَكَذَا وَشَبَّكَ بَيْنَ أَصَابِعِهِ قَالُوا فَكَيْفَ نَصْنَعُ يَا رَسُولَ اللَّهِ إِذَا كَانَ ذَلِكَ قَالَ تَأْخُذُونَ مَا تَعْرِفُونَ وَتَذَرُونَ مَا تُنْكِرُونَ وَتُقْبِلُونَ عَلَى خَاصَّتِكُمْ وَتَدَعُونَ عَامَّتَكُمْ ‏ ‏حَدَّثَنَاه ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏وَمَعْنَاهُ إِلَّا أَنَّهُ قَالَ وَتَبْقَى ‏ ‏حُثَالَةٌ ‏ ‏مِنْ النَّاسِ وَتَدَعُونَ أَمْرَ عَامَّتِكُمْ ‏","","",""],[6767,6767,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ اللَّهِ الْمَعَافِرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْبَرْحِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخْرَجَ ‏ ‏صَدَقَةً ‏ ‏فَلَمْ يَجِدْ إِلَّا بَرْبَرِيًّا فَلْيَرُدَّهَا ‏","","",""],[6768,6768,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حُيَيِّ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِسَعْدٍ ‏ ‏وَهُوَ يَتَوَضَّأُ فَقَالَ ‏ ‏مَا هَذَا السَّرَفُ يَا ‏ ‏سَعْدُ ‏ ‏قَالَ أَفِي الْوُضُوءِ سَرَفٌ قَالَ نَعَمْ وَإِنْ كُنْتَ عَلَى نَهْرٍ ‏ ‏جَارٍ ‏","","",""],[6769,6769,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُوضَعُ الْمَوَازِينُ يَوْمَ الْقِيَامَةِ فَيُؤْتَى بِالرَّجُلِ فَيُوضَعُ فِي كِفَّةٍ فَيُوضَعُ مَا أُحْصِيَ عَلَيْهِ فَتَمَايَلَ بِهِ الْمِيزَانُ قَالَ فَيُبْعَثُ بِهِ إِلَى النَّارِ قَالَ فَإِذَا ‏ ‏أُدْبِرَ ‏ ‏بِهِ إِذَا صَائِحٌ يَصِيحُ مِنْ عِنْدِ الرَّحْمَنِ يَقُولُ لَا تَعْجَلُوا ‏ ‏لَا تَعْجَلُوا فَإِنَّهُ قَدْ بَقِيَ لَهُ فَيُؤْتَى بِبِطَاقَةٍ فِيهَا لَا إِلَهَ إِلَّا اللَّهُ فَتُوضَعُ مَعَ الرَّجُلِ فِي كِفَّةٍ حَتَّى يَمِيلَ بِهِ الْمِيزَانُ ‏","","",""],[6770,6770,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏وَاهِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّهُ ‏ ‏قَالَ رَأَيْتُ فِيمَا يَرَى النَّائِمُ لَكَأَنَّ فِي إِحْدَى إِصْبَعَيَّ سَمْنًا وَفِي الْأُخْرَى عَسَلًا فَأَنَا أَلْعَقُهُمَا فَلَمَّا أَصْبَحْتُ ذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏تَقْرَأُ الْكِتَابَيْنِ التَّوْرَاةَ وَالْفُرْقَانَ فَكَانَ يَقْرَؤُهُمَا ‏","","",""],[6771,6771,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَامَ مِنْ اللَّيْلِ ‏ ‏يُصَلِّي فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ فَقَالَ لَهُمْ لَقَدْ ‏ ‏أُعْطِيتُ اللَّيْلَةَ خَمْسًا مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي أَمَّا أَنَا فَأُرْسِلْتُ إِلَى النَّاسِ كُلِّهِمْ عَامَّةً وَكَانَ مَنْ قَبْلِي إِنَّمَا يُرْسَلُ إِلَى قَوْمِهِ وَنُصِرْتُ عَلَى الْعَدُوِّ بِالرُّعْبِ وَلَوْ كَانَ بَيْنِي وَبَيْنَهُمْ مَسِيرَةُ شَهْرٍ لَمُلِئَ مِنْهُ رُعْبًا وَأُحِلَّتْ لِي الْغَنَائِمُ آكُلُهَا وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ أَكْلَهَا كَانُوا يُحْرِقُونَهَا وَجُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ وَالْخَامِسَةُ هِيَ مَا هِيَ قِيلَ لِي ‏ ‏سَلْ ‏ ‏فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[6772,6772,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏رِشْدِينُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ يَدْخُلُ مِنْ هَذَا الْبَابِ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَدَخَلَ ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏","","",""],[6773,6773,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ أَبِي رُقَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏وَلَا حَسَدَ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ ‏","","",""],[6774,6774,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ هَلْ تُحِسُّ بِالْوَحْيِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ أَسْمَعُ ‏ ‏صَلَاصِلَ ‏ ‏ثُمَّ أَسْكُتُ عِنْدَ ذَلِكَ فَمَا مِنْ مَرَّةٍ يُوحَى إِلَيَّ إِلَّا ظَنَنْتُ أَنَّ نَفْسِي تَفِيضُ ‏","","",""],[6775,6775,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏جُنْدُبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَطَلَعَتْ الشَّمْسُ فَقَالَ ‏ ‏يَأْتِي اللَّهَ قَوْمٌ يَوْمَ الْقِيَامَةِ نُورُهُمْ كَنُورِ الشَّمْسِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنَحْنُ هُمْ يَا رَسُولَ اللَّهِ قَالَ لَا وَلَكُمْ خَيْرٌ كَثِيرٌ وَلَكِنَّهُمْ الْفُقَرَاءُ ‏ ‏وَالْمُهَاجِرُونَ ‏ ‏الَّذِينَ يُحْشَرُونَ مِنْ أَقْطَارِ الْأَرْضِ وَقَالَ ‏ ‏طُوبَى ‏ ‏لِلْغُرَبَاءِ ‏ ‏طُوبَى ‏ ‏لِلْغُرَبَاءِ ‏ ‏طُوبَى ‏ ‏لِلْغُرَبَاءِ فَقِيلَ مَنْ الْغُرَبَاءُ يَا رَسُولَ اللَّهِ قَالَ نَاسٌ صَالِحُونَ فِي نَاسِ سَوْءٍ كَثِيرٍ مَنْ ‏ ‏يَعْصِيهِمْ أَكْثَرُ مِمَّنْ يُطِيعُهُمْ ‏","","",""],[6776,6776,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ حَقَّ كَبِيرِنَا فَلَيْسَ مِنَّا ‏","","",""],[6777,6777,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا رَجُلٌ ‏ ‏يَتَبَخْتَرُ ‏ ‏فِي ‏ ‏حُلَّةٍ ‏ ‏إِذْ أَمَرَ اللَّهُ عَزَّ وَجَلَّ بِهِ الْأَرْضَ ‏ ‏فَأَخَذَتْهُ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا أَوْ ‏ ‏يَتَجَرْجَرُ ‏ ‏فِيهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[6778,6778,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏أُسَامَةُ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ شُعَيْبٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي أَنْزِعُ فِي حَوْضِي حَتَّى إِذَا مَلَأْتُهُ لِأَهْلِي وَرَدَ عَلَيَّ الْبَعِيرُ لِغَيْرِي فَسَقَيْتُهُ فَهَلْ لِي فِي ذَلِكَ مِنْ أَجْرٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُلِّ ‏ ‏ذَاتِ كَبِدٍ ‏ ‏حَرَّى ‏ ‏أَجْرٌ ‏","","",""],[6779,6779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ يَعْنِي الْخَطَّابِيَّ ‏ ‏حَدَّثَنِي ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْوَلِيدِ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَسَّ ذَكَرَهُ فَلْيَتَوَضَّأْ وَأَيُّمَا امْرَأَةٍ مَسَّتْ فَرْجَهَا فَلْتَتَوَضَّأْ ‏","","",""],[6780,6780,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتُ صَلَاةِ الظُّهْرِ إِذَا زَالَتْ الشَّمْسُ وَكَانَ ظِلُّ الرَّجُلِ كَطُولِهِ مَا لَمْ تَحْضُرْ الْعَصْرُ وَوَقْتُ صَلَاةِ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ وَوَقْتُ صَلَاةِ الْمَغْرِبِ مَا لَمْ يَغِبْ ‏ ‏الشَّفَقُ ‏ ‏وَوَقْتُ صَلَاةِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ وَوَقْتُ صَلَاةِ الصُّبْحِ مِنْ طُلُوعِ الْفَجْرِ مَا لَمْ تَطْلُعْ الشَّمْسُ فَإِذَا طَلَعَتْ فَأَمْسِكْ فَإِنَّهَا تَطْلُعُ بَيْنَ ‏ ‏قَرْنَيْ شَيْطَانٍ ‏ ‏أَوْ مَعَ ‏ ‏قَرْنَيْ شَيْطَانٍ ‏","","",""],[6781,6781,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي حَرْبٍ الدَّيْلِيِّ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَظَلَّتْ ‏ ‏الْخَضْرَاءُ ‏ ‏وَلَا ‏ ‏أَقَلَّتْ ‏ ‏الْغَبْرَاءُ ‏ ‏مِنْ رَجُلٍ أَصْدَقَ لَهْجَةً مِنْ ‏ ‏أَبِي ذَرٍّ ‏","","",""],[6782,6782,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَاهُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذُكِرَتْ الْأَعْمَالُ فَقَالَ ‏ ‏مَا مِنْ أَيَّامٍ الْعَمَلُ فِيهِنَّ أَفْضَلُ مِنْ هَذِهِ الْعَشْرِ قَالُوا يَا رَسُولَ اللَّهِ وَلَا الْجِهَادُ قَالَ فَأَكْبَرَهُ قَالَ وَلَا الْجِهَادُ إِلَّا أَنْ يَخْرُجَ رَجُلٌ بِنَفْسِهِ وَمَالِهِ فِي سَبِيلِ اللَّهِ ثُمَّ تَكُونَ ‏ ‏مُهْجَةُ ‏ ‏نَفْسِهِ فِيهِ ‏","","",""],[6783,6783,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَمَّا تُوُفِّيَ ‏ ‏إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَسَفَتْ الشَّمْسُ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى رَكْعَتَيْنِ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ مِثْلَ قِيَامِهِ ثُمَّ سَجَدَ مِثْلَ رُكُوعِهِ فَصَلَّى رَكْعَتَيْنِ كَذَلِكَ ثُمَّ سَلَّمَ ‏","","",""],[6784,6784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏شُرَحْبِيلُ بْنُ شَرِيكٍ الْمَعَافِرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ رَافِعٍ التَّنُوخِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أُبَالِي مَا أَتَيْتُ ‏ ‏أَوْ مَا رَكِبْتُ ‏ ‏إِذَا أَنَا شَرِبْتُ ‏ ‏تِرْيَاقًا ‏ ‏أَوْ تَعَلَّقْتُ ‏ ‏تَمِيمَةً ‏ ‏أَوْ قُلْتُ الشِّعْرَ مِنْ قِبَلِ نَفْسِي ‏","","",""],[6785,6785,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ سَيْفٍ الْمَعَافِرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ رَأَى ‏ ‏فَاطِمَةَ ‏ ‏ابْنَتَهُ فَقَالَ لَهَا مِنْ أَيْنَ أَقْبَلْتِ قَالَتْ أَقْبَلْتُ مِنْ وَرَاءِ جَنَازَةِ هَذَا الرَّجُلِ قَالَ فَهَلْ بَلَغْتِ مَعَهُمْ ‏ ‏الْكُدَى ‏ ‏قَالَتْ لَا وَكَيْفَ أَبْلُغُهَا وَقَدْ سَمِعْتُ مِنْكَ مَا سَمِعْتُ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْ بَلَغْتِ مَعَهُمْ ‏ ‏الْكُدَى ‏ ‏مَا رَأَيْتِ الْجَنَّةَ حَتَّى يَرَاهَا جَدُّ أَبِيكِ ‏","","",""],[6786,6786,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَيَّاشِ بْنِ عَبَّاسٍ الْقِتْبَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عِيسَى بْنَ هِلَالٍ الصَّدَفِيَّ ‏ ‏وَأَبَا عَبْدِ الرَّحْمَنِ الْحُبُلِيَّ ‏ ‏يَقُولَانِ سَمِعْنَا ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ فِي آخِرِ أُمَّتِي رِجَالٌ يَرْكَبُونَ عَلَى ‏ ‏السُّرُوجِ ‏ ‏كَأَشْبَاهِ الرِّجَالِ يَنْزِلُونَ عَلَى أَبْوَابِ الْمَسْجِدِ نِسَاؤُهُمْ كَاسِيَاتٌ عَارِيَاتٌ عَلَى رُءُوسِهِمْ ‏ ‏كَأَسْنِمَةِ ‏ ‏الْبُخْتِ ‏ ‏الْعِجَافِ ‏ ‏الْعَنُوهُنَّ فَإِنَّهُنَّ مَلْعُونَاتٌ لَوْ كَانَتْ وَرَاءَكُمْ أُمَّةٌ مِنْ الْأُمَمِ لَخَدَمْنَ نِسَاؤُكُمْ نِسَاءَهُمْ كَمَا يَخْدِمْنَكُمْ نِسَاءُ الْأُمَمِ قَبْلَكُمْ ‏","","",""],[6787,6787,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ مَظْلُومًا فَلَهُ الْجَنَّةُ ‏","","",""],[6788,6788,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَمَّعَ النَّاسَ بِعَمَلِهِ ‏ ‏سَمَّعَ اللَّهُ بِهِ سَامِعَ خَلْقِهِ وَحَقَّرَهُ وَصَغَّرَهُ ‏","","",""],[6789,6789,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرٍو ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏","","",""],[6790,6790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏ذَكَرْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّوْمَ فَقَالَ ‏ ‏صُمْ مِنْ كُلِّ عَشَرَةِ أَيَّامٍ يَوْمًا وَلَكَ أَجْرُ التِّسْعَةِ قَالَ فَقُلْتُ إِنِّي أَقْوَى مِنْ ذَلِكَ قَالَ فَصُمْ مِنْ كُلِّ تِسْعَةِ أَيَّامٍ يَوْمًا وَلَكَ أَجْرُ الثَّمَانِيَةِ قَالَ فَقُلْتُ إِنِّي أَقْوَى مِنْ ذَلِكَ قَالَ صُمْ مِنْ كُلِّ ثَمَانِيَةِ أَيَّامٍ يَوْمًا وَلَكَ أَجْرُ تِلْكَ السَّبْعَةِ قَالَ قُلْتُ إِنِّي أَقْوَى مِنْ ذَلِكَ قَالَ فَلَمْ يَزَلْ حَتَّى قَالَ صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا ‏","","",""],[6791,6791,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَقْلُ ‏ ‏شِبْهِ الْعَمْدِ ‏ ‏مُغَلَّظَةٌ ‏ ‏مِثْلُ ‏ ‏عَقْلِ ‏ ‏الْعَمْدِ وَلَا يُقْتَلُ صَاحِبُهُ وَمَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَلَا ‏ ‏رَصَدَ ‏ ‏بِطَرِيقٍ ‏","","",""],[6792,6792,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَابَاهُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُبَاهِي مَلَائِكَتَهُ عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏بِأَهْلِ ‏ ‏عَرَفَةَ ‏ ‏فَيَقُولُ ‏ ‏انْظُرُوا إِلَى عِبَادِي أَتَوْنِي ‏ ‏شُعْثًا ‏ ‏غُبْرًا ‏","","",""],[6793,6793,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ خَطَأً ‏ ‏فَدِيَتُهُ ‏ ‏مِائَةٌ مِنْ الْإِبِلِ ثَلَاثُونَ ‏ ‏ابْنَةَ مَخَاضٍ ‏ ‏وَثَلَاثُونَ ‏ ‏ابْنَةَ لَبُونٍ ‏ ‏وَثَلَاثُونَ ‏ ‏جَذَعَةً ‏ ‏وَعَشَرَةُ ‏ ‏بَنِي لَبُونٍ ‏ ‏ذُكْرَانٍ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَوِّمُهَا عَلَى أَثْمَانِ الْإِبِلِ فَإِذَا هَانَتْ نَقَصَ مِنْ قِيمَتِهَا وَإِذَا غَلَتْ رَفَعَ فِي قِيمَتِهَا عَلَى نَحْوِ الزَّمَانِ مَا كَانَتْ فَبَلَغَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ أَرْبَعِ مِائَةِ دِينَارٍ إِلَى ثَمَانِ مِائَةِ دِينَارٍ أَوْ عِدْلَهَا مِنْ ‏ ‏الْوَرِقِ ‏ ‏ثَمَانِيَةَ آلَافٍ ‏","","",""],[6794,6794,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى أَنَّ ‏ ‏الْعَقْلَ ‏ ‏مِيرَاثٌ بَيْنَ وَرَثَةِ الْقَتِيلِ عَلَى فَرَائِضِهِمْ ‏","","",""],[6795,6795,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِي الْأَنْفِ إِذَا ‏ ‏جُدِعَ ‏ ‏كُلُّهُ ‏ ‏الدِّيَةَ ‏ ‏كَامِلَةً وَإِذَا ‏ ‏جُدِعَتْ ‏ ‏أَرْنَبَتُهُ ‏ ‏نِصْفَ ‏ ‏الدِّيَةِ ‏ ‏وَفِي الْعَيْنِ نِصْفَ ‏ ‏الدِّيَةِ ‏ ‏وَفِي الْيَدِ نِصْفَ ‏ ‏الدِّيَةِ ‏ ‏وَفِي الرِّجْلِ نِصْفَ ‏ ‏الدِّيَةِ ‏ ‏وَقَضَى أَنْ ‏ ‏يَعْقِلَ ‏ ‏عَنْ الْمَرْأَةِ ‏ ‏عَصَبَتُهَا ‏ ‏مَنْ كَانُوا وَلَا ‏ ‏يَرِثُوا ‏ ‏مِنْهَا إِلَّا مَا فَضَلَ عَنْ وَرَثَتِهَا وَإِنْ قُتِلَتْ ‏ ‏فَعَقْلُهَا ‏ ‏بَيْنَ وَرَثَتِهَا وَهُمْ يَقْتُلُونَ قَاتِلَهَا وَقَضَى أَنَّ ‏ ‏عَقْلَ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏نِصْفُ ‏ ‏عَقْلِ ‏ ‏الْمُسْلِمِينَ وَهُمْ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏","","",""],[6796,6796,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَدَّادٌ أَبُو طَلْحَةَ الرَّاسِبِيُّ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْوَازِعِ جَابِرَ بْنَ عَمْرٍو ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ قَوْمٍ جَلَسُوا مَجْلِسًا لَمْ يَذْكُرُوا اللَّهَ فِيهِ إِلَّا رَأَوْهُ حَسْرَةً يَوْمَ الْقِيَامَةِ ‏","","",""],[6797,6797,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يَدْخُلُ ‏ ‏الْحَائِطَ ‏ ‏قَالَ ‏ ‏يَأْكُلُ غَيْرَ مُتَّخِذٍ ‏ ‏خُبْنَةً ‏","","",""],[6798,6798,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي الْوَضَّاحِ ‏ ‏حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ اللَّهِ بْنِ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏حَنَانُ بْنُ خَارِجَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ ‏ ‏عَلَوِيٌّ ‏ ‏جَرِيءٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنَا عَنْ الْهِجْرَةِ إِلَيْكَ أَيْنَمَا كُنْتَ أَوْ لِقَوْمٍ خَاصَّةً أَمْ إِلَى أَرْضٍ مَعْلُومَةٍ أَمْ إِذَا مُتَّ انْقَطَعَتْ قَالَ فَسَكَتَ عَنْهُ يَسِيرًا ثُمَّ قَالَ أَيْنَ السَّائِلُ قَالَ هَا هُوَ ذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏الْهِجْرَةُ أَنْ تَهْجُرَ ‏ ‏الْفَوَاحِشَ ‏ ‏مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَتُقِيمَ الصَّلَاةَ ‏ ‏وَتُؤْتِيَ الزَّكَاةَ ثُمَّ أَنْتَ مُهَاجِرٌ وَإِنْ مُتَّ بِالْحَضَرِ ‏","","",""],[6799,6799,"","","‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏ابْتِدَاءً مِنْ نَفْسِهِ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنَا عَنْ ثِيَابِ أَهْلِ الْجَنَّةِ خَلْقًا تُخْلَقُ أَمْ نَسْجًا تُنْسَجُ فَضَحِكَ بَعْضُ الْقَوْمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّ تَضْحَكُونَ مِنْ جَاهِلٍ يَسْأَلُ عَالِمًا ثُمَّ ‏ ‏أَكَبَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ أَيْنَ السَّائِلُ قَالَ هُوَ ذَا أَنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لَا بَلْ ‏ ‏تَشَقَّقُ عَنْهَا ثَمَرُ الْجَنَّةِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[6800,6800,"","","‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ سُلَيْمَانَ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏مُثِّلَ ‏ ‏بِهِ أَوْ حُرِّقَ بِالنَّارِ فَهُوَ حُرٌّ وَهُوَ ‏ ‏مَوْلَى ‏ ‏اللَّهِ وَرَسُولِهِ قَالَ فَأُتِيَ بِرَجُلٍ قَدْ خُصِيَ يُقَالُ لَهُ ‏ ‏سَنْدَرٌ ‏ ‏فَأَعْتَقَهُ ‏ ‏ثُمَّ أَتَى ‏ ‏أَبَا بَكْرٍ ‏ ‏بَعْدَ وَفَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَنَعَ إِلَيْهِ خَيْرًا ‏ ‏ثُمَّ أَتَى ‏ ‏عُمَرَ ‏ ‏بَعْدَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَصَنَعَ إِلَيْهِ خَيْرًا ثُمَّ إِنَّهُ أَرَادَ أَنْ يَخْرُجَ إِلَى ‏ ‏مِصْرَ ‏ ‏فَكَتَبَ لَهُ ‏ ‏عُمَرُ ‏ ‏إِلَى ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنْ اصْنَعْ بِهِ خَيْرًا أَوْ احْفَظْ وَصِيَّةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ ‏","","",""]];
